capture_editorial_notification.definition:
CREATE OR REPLACE FUNCTION public.capture_editorial_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare changed boolean; hours integer;
begin
  changed := TG_OP='INSERT';
  if TG_OP='UPDATE' then
    changed := new.assigned_to is distinct from old.assigned_to
      or new.review_due_at is distinct from old.review_due_at
      or (new.status in ('draft','pending_review')) <> (old.status in ('draft','pending_review'));
  end if;
  if changed then
    new.notification_epoch := coalesce(new.notification_epoch,0)+1;
    if new.assigned_to is not null and new.status in ('draft','pending_review') then
      new.review_assigned_at := statement_timestamp();
      if new.review_due_at is null then
        select deadline_hours into hours from public.editorial_notification_policy;
        new.review_due_at := statement_timestamp() + make_interval(hours=>hours);
      end if;
    end if;
  end if;
  return new;
end $function$

edge_api_choose_review.definition:
CREATE OR REPLACE FUNCTION public.edge_api_choose_review(p_user_id uuid, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_concept uuid;
begin
  select (now() at time zone timezone)::date into v_today
    from public.profiles where id = p_user_id for update;
  if v_today is null then return null; end if;
  v_today := coalesce(p_today, v_today);

  if exists(select 1 from public.daily_reviews
    where user_id = p_user_id and assigned_for = v_today) then
    return public.edge_api_review_payload(p_user_id, v_today);
  end if;
  if exists(select 1 from public.daily_assignments
    where user_id = p_user_id and assigned_for = v_today) then
    return null;
  end if;
  -- An intentionally empty followed set cannot be widened by a review.
  select a.concept_id into v_concept
    from public.daily_assignments a
    join public.concepts c on c.id = a.concept_id and c.status = 'published'
    join public.topics t on t.id = c.topic_id and t.is_active
    join public.subtopics s on s.id = c.subtopic_id and s.is_active
    join public.user_topics ut on ut.topic_id = c.topic_id and ut.user_id = p_user_id
    left join lateral (
      select max(r.assigned_for) as last_review from public.daily_reviews r
       where r.user_id = p_user_id and r.concept_id = a.concept_id
    ) seen on true
   where a.user_id = p_user_id and a.completed_at is not null
   order by seen.last_review asc nulls first, a.assigned_for, a.concept_id
   limit 1;
  if v_concept is null then return null; end if;
  insert into public.daily_reviews(user_id, concept_id, assigned_for)
  values (p_user_id, v_concept, v_today)
  on conflict(user_id, assigned_for) do nothing;
  return public.edge_api_review_payload(p_user_id, v_today);
end
$function$

edge_api_complete_daily.definition:
CREATE OR REPLACE FUNCTION public.edge_api_complete_daily(p_user_id uuid, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_assignment record;
  v_subtopic jsonb;
begin
  select (now() at time zone timezone)::date into v_today
    from public.profiles where id = p_user_id for update;
  if v_today is null then return null; end if;
  v_today := coalesce(p_today, v_today);

  update public.daily_assignments
     set completed_at = coalesce(completed_at, now())
   where id = (
     select id from public.daily_assignments
      where user_id = p_user_id
        and assigned_for in (v_today, v_today - 1)
        and not exists(select 1 from public.daily_reviews r
          where r.user_id = p_user_id and r.assigned_for >= daily_assignments.assigned_for)
      order by assigned_for desc limit 1
   )
  returning id, concept_id, assigned_for, completed_at into v_assignment;
  if not found then return null; end if;

  insert into public.user_concept_completions
    (user_id, concept_id, source_assignment_id, completed_at)
  values (p_user_id, v_assignment.concept_id, v_assignment.id, v_assignment.completed_at)
  on conflict(user_id, concept_id) do nothing;
  v_subtopic := public.edge_api_record_subtopic_completion(p_user_id, v_assignment.concept_id);
  perform public.edge_api_award_eligible(p_user_id);
  return jsonb_build_object(
    'completed', true, 'assigned_for', v_assignment.assigned_for,
    'stats', public.edge_api_stats(p_user_id),
    'subtopic_completion', v_subtopic
  );
end
$function$

edge_api_complete_review.definition:
CREATE OR REPLACE FUNCTION public.edge_api_complete_review(p_user_id uuid, p_review_id uuid, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_day date;
begin
  select (now() at time zone timezone)::date into v_today
    from public.profiles where id = p_user_id for update;
  if v_today is null then return null; end if;
  v_today := coalesce(p_today, v_today);
  update public.daily_reviews r
     set completed_at = coalesce(completed_at, now())
   where r.id = p_review_id and r.user_id = p_user_id
     and (r.completed_at is not null or (
       r.assigned_for in (v_today, v_today - 1)
       and not exists(select 1 from public.daily_assignments a
         where a.user_id = p_user_id and a.assigned_for > r.assigned_for)
       and not exists(select 1 from public.daily_reviews newer
         where newer.user_id = p_user_id and newer.assigned_for > r.assigned_for)
     ))
  returning r.assigned_for into v_day;
  if not found then return null; end if;
  perform public.edge_api_award_eligible(p_user_id);
  return jsonb_build_object(
    'completed', true, 'assigned_for', v_day,
    'stats', public.edge_api_stats(p_user_id),
    'subtopic_completion', null
  );
end
$function$

edge_api_daily.definition:
CREATE OR REPLACE FUNCTION public.edge_api_daily(p_user_id uuid, p_low integer DEFAULT 10, p_reserve integer DEFAULT 60, p_active_days integer DEFAULT 90, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_today date;
  v_timezone text;
  v_concept uuid;
  v_topic uuid;
  v_assignment uuid;
  v_payload jsonb;
begin
  if p_low < 0 or p_low > 30 or p_reserve < 1 or p_reserve > 365
     or p_active_days < 1 or p_active_days > 365 then
    raise exception 'Invalid supply configuration';
  end if;

  -- Match the legacy-user safety net without restoring deliberately unfollowed topics.
  with created as (
    insert into public.profiles(id, display_name)
    select p_user_id, split_part(u.email, '@', 1)
      from auth.users u where u.id = p_user_id
    on conflict(id) do nothing returning id
  ), prefs as (
    insert into public.notification_preferences(user_id) values (p_user_id)
    on conflict(user_id) do nothing
  )
  insert into public.user_topics(user_id, topic_id)
  select created.id, t.id from created cross join public.topics t where t.is_active
  on conflict do nothing;

  select timezone into v_timezone
    from public.profiles where id = p_user_id for update;
  if v_timezone is null then
    raise exception 'Profile unavailable';
  end if;
  v_today := coalesce(p_today, (now() at time zone v_timezone)::date);

  if exists(select 1 from public.daily_reviews
    where user_id = p_user_id and assigned_for = v_today) then
    return jsonb_build_object('assigned_for', v_today, 'reason', 'catalog_exhausted',
      'detail', 'You have already been assigned every available concept.');
  end if;
  if exists(select 1 from public.daily_assignments
    where user_id = p_user_id and assigned_for = v_today) then
    v_payload := public.edge_api_daily_payload(p_user_id, v_today);
    if v_payload is not null then return v_payload; end if;
    return jsonb_build_object('assigned_for', v_today, 'reason', 'catalog_exhausted',
      'detail', 'You have already been assigned every available concept.');
  end if;

  if not exists(select 1 from public.user_topics ut
    join public.topics t on t.id = ut.topic_id and t.is_active
    where ut.user_id = p_user_id) then
    return jsonb_build_object('assigned_for', v_today, 'reason', 'personalization_required',
      'detail', 'Follow at least one topic to receive a daily concept.');
  end if;

  -- Move the most recent unfinished followed lesson, retaining its identity and timestamp.
  with pending as (
    select a.id from public.daily_assignments a
    join public.concepts c on c.id = a.concept_id and c.status = 'published'
    join public.topics t on t.id = c.topic_id and t.is_active
    join public.subtopics s on s.id = c.subtopic_id and s.is_active
    join public.user_topics ut on ut.topic_id = c.topic_id and ut.user_id = p_user_id
    where a.user_id = p_user_id and a.completed_at is null and a.assigned_for < v_today
    order by a.assigned_for desc, a.id limit 1
  )
  update public.daily_assignments a set assigned_for = v_today
    from pending where a.id = pending.id returning a.concept_id into v_concept;
  if v_concept is not null then
    select topic_id into v_topic from public.concepts where id = v_concept;
    perform public.edge_api_signal_supply(p_user_id, v_topic, p_low, p_reserve, p_active_days);
    return public.edge_api_daily_payload(p_user_id, v_today);
  end if;

  with pool as (
    select c.id, c.topic_id, coalesce(c.difficulty, 1) as level,
      (select count(*) from jsonb_array_elements_text(
        coalesce(c.curriculum->'prerequisites', '[]'::jsonb)) required(slug)
        where not exists(select 1 from public.daily_assignments learned
          join public.concepts prior on prior.id = learned.concept_id
          where learned.user_id = p_user_id and learned.completed_at is not null
            and prior.slug = required.slug)) as unmet
      from public.concepts c
      join public.topics t on t.id = c.topic_id and t.is_active
      join public.subtopics s on s.id = c.subtopic_id and s.is_active
      where c.status = 'published'
        and exists(select 1 from public.user_topics ut
          where ut.user_id = p_user_id and ut.topic_id = c.topic_id)
        and not exists(select 1 from public.daily_assignments a
          where a.user_id = p_user_id and a.concept_id = c.id)
  ), last_seen as (
    select c.topic_id, max(a.assigned_for) as seen_on
      from public.daily_assignments a
      join public.concepts c on c.id = a.concept_id and c.status = 'published'
     where a.user_id = p_user_id group by c.topic_id
  )
  select pool.id, pool.topic_id into v_concept, v_topic
    from pool left join last_seen on last_seen.topic_id = pool.topic_id
   order by last_seen.seen_on asc nulls first, pool.unmet asc, pool.level asc, random()
   limit 1;

  if v_concept is not null then
    begin
      insert into public.daily_assignments(id, user_id, concept_id, assigned_for)
      values (gen_random_uuid(), p_user_id, v_concept, v_today)
      on conflict(user_id, assigned_for) do nothing returning id into v_assignment;
    exception when unique_violation then
      v_assignment := null;
    end;
    if v_assignment is not null then
      perform public.edge_api_signal_supply(p_user_id, v_topic, p_low, p_reserve, p_active_days);
      v_payload := public.edge_api_daily_payload(p_user_id, v_today);
      if v_payload is not null then return v_payload; end if;
    else
      v_payload := public.edge_api_daily_payload(p_user_id, v_today);
      if v_payload is not null then return v_payload; end if;
    end if;
  else
    -- Request future supply in a followed topic without waiting for generation.
    select ut.topic_id into v_topic from public.user_topics ut
    join public.topics t on t.id = ut.topic_id and t.is_active
    left join (
      select c.topic_id, max(a.assigned_for) as seen_on
      from public.daily_assignments a
      join public.concepts c on c.id = a.concept_id and c.status = 'published'
      where a.user_id = p_user_id group by c.topic_id
    ) seen on seen.topic_id = ut.topic_id
    where ut.user_id = p_user_id
    order by seen.seen_on asc nulls first limit 1;
    if v_topic is not null then
      perform public.edge_api_signal_supply(p_user_id, v_topic, p_low, p_reserve, p_active_days);
    end if;
  end if;
  return jsonb_build_object('assigned_for', v_today, 'reason', 'catalog_exhausted',
    'detail', 'You have already been assigned every available concept.');
end
$function$

edge_api_editorial_activity.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_activity(p_user_id uuid, p_session_id uuid, p_aal text, p_cursor uuid, p_topic_id uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_items jsonb;
  v_next uuid;
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    return jsonb_build_object('error', 'invalid_page');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id, p_session_id, p_aal, 'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  with page as (
    select e.id, to_jsonb(e) || jsonb_build_object('created_at',
      public.edge_api_editorial_utc_iso(e.created_at)) as item from public.editorial_workflow_events e
     where (p_cursor is null or e.id > p_cursor)
       and (p_topic_id is null or e.topic_id = p_topic_id)
     order by e.id limit p_limit + 1
  ), numbered as (
    select page.*, row_number() over(order by id) as position from page
  )
  select coalesce(jsonb_agg(item order by id) filter(where position <= p_limit), '[]'::jsonb),
         (select id from numbered where position = p_limit
           and exists(select 1 from numbered where position > p_limit))
    into v_items, v_next from numbered;
  return jsonb_build_object('items', v_items, 'next_cursor', v_next);
end
$function$

edge_api_editorial_authorize_any.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_authorize_any(p_user_id uuid, p_session_id uuid, p_aal text, p_capabilities text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_member jsonb;
begin
  v_context := public.edge_api_editorial_me(p_user_id, p_session_id, p_aal);
  if v_context ? 'error' then return v_context; end if;
  v_member := v_context -> 'member';
  if p_capabilities is null or not (v_member -> 'capabilities' ?| p_capabilities) then
    return jsonb_build_object('error', 'permission');
  end if;
  if v_member ->> 'approved_name' is null then
    return jsonb_build_object('error', 'profile_required');
  end if;
  if (v_member ->> 'require_mfa')::boolean and p_aal is distinct from 'aal2' then
    return jsonb_build_object('error', 'mfa_required');
  end if;
  return v_member;
end
$function$

edge_api_editorial_cancel_generation_job.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_cancel_generation_job(p_user_id uuid, p_session_id uuid, p_aal text, p_job_id uuid, p_request_id uuid, p_note text, p_expected_token text, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_receipt public.editorial_request_receipts%rowtype;
  v_job public.editorial_generation_jobs%rowtype;
  v_visible jsonb;
  v_note text;
begin
  if p_job_id is null or p_request_id is null or p_note is null
    or length(p_note)<10 or length(p_note)>4000
    or p_expected_token is null or p_expected_token !~ '^[a-f0-9]{64}$'
    or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('error','invalid');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  select * into v_receipt from public.editorial_request_receipts
    where actor_id=p_user_id and request_id=p_request_id;
  if found then
    if v_receipt.fingerprint<>p_fingerprint then
      return jsonb_build_object('error','receipt_conflict');
    end if;
    return v_receipt.result;
  end if;
  select * into v_job from public.editorial_generation_jobs
    where id=p_job_id for update;
  if not found then return jsonb_build_object('error','job_not_found'); end if;
  v_visible := public.edge_api_editorial_job_public(v_job);
  if v_visible->>'token'<>p_expected_token then
    return jsonb_build_object('error','stale_revision');
  end if;
  if v_job.status not in ('pending','generating') then
    return jsonb_build_object('error','review_conflict',
      'message','Only pending or generating jobs can be cancelled');
  end if;
  v_note := regexp_replace(p_note,'^[[:space:]]+|[[:space:]]+$','','g');
  if length(v_note)<10 then
    return jsonb_build_object('error','review_conflict',
      'message','Record a substantive note of at least 10 characters');
  end if;
  update public.editorial_generation_jobs set status='cancelled',
    failure_code=null,result_revision_id=null,
    claim_token=case when v_job.status='generating' then claim_token else null end,
    claimed_at=case when v_job.status='generating' then claimed_at else null end,
    available_at=now()+interval '5 minutes',updated_at=clock_timestamp()
    where id=p_job_id;
  insert into public.editorial_workflow_events
    (revision_id,concept_id,topic_id,actor_id,registered_name,action,note,details)
    values(v_job.source_revision_id,v_job.concept_id,v_job.topic_id,
      p_user_id,v_actor->>'approved_name','comment',v_note,
      jsonb_build_object('generation_job_id',p_job_id,
        'generation_status','cancelled'));
  select public.edge_api_editorial_job_public(j) into v_visible
    from public.editorial_generation_jobs j where id=p_job_id;
  insert into public.editorial_request_receipts
    (actor_id,request_id,fingerprint,result)
    values(p_user_id,p_request_id,p_fingerprint,v_visible);
  return v_visible;
end
$function$

edge_api_editorial_concept_action.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_concept_action(p_user_id uuid, p_session_id uuid, p_aal text, p_concept_id uuid, p_request_id uuid, p_note text, p_expected_token text, p_action text, p_quality jsonb, p_body_valid boolean, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_receipt public.editorial_request_receipts%rowtype;
  v_concept public.concepts%rowtype;
  v_topic_active boolean;
  v_subtopic_active boolean;
  v_subtopic_slug text;
  v_snapshot jsonb;
  v_body jsonb;
  v_token text;
  v_note text;
  v_problem text;
  v_event uuid;
  v_result jsonb;
  v_capability text;
begin
  if p_concept_id is null or p_request_id is null or p_note is null
    or length(p_note)<10 or length(p_note)>4000
    or p_expected_token is null or p_expected_token !~ '^[a-f0-9]{64}$'
    or p_action is null or p_action not in ('comment','retire','attest')
    or ((p_action='attest') is distinct from (p_quality is not null))
    or (p_quality is not null and not coalesce(
      public.edge_api_editorial_quality_valid(p_quality),false))
    or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('error','invalid');
  end if;
  v_capability := case when p_action='comment' then 'review' else 'publish' end;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,v_capability);
  if v_actor ? 'error' then return v_actor; end if;
  if p_action='attest' then
    v_actor := public.edge_api_editorial_authorize(
      p_user_id,p_session_id,p_aal,'approve');
    if v_actor ? 'error' then return v_actor; end if;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,v_capability);
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,v_capability);
  if v_actor ? 'error' then return v_actor; end if;
  if p_action='attest' then
    v_actor := public.edge_api_editorial_authorize(
      p_user_id,p_session_id,p_aal,'approve');
    if v_actor ? 'error' then return v_actor; end if;
  end if;
  select * into v_receipt from public.editorial_request_receipts
    where actor_id=p_user_id and request_id=p_request_id;
  if found then
    if v_receipt.fingerprint<>p_fingerprint then
      return jsonb_build_object('error','receipt_conflict');
    end if;
    return v_receipt.result;
  end if;
  select c.* into v_concept from public.concepts c
    join public.topics t on t.id=c.topic_id
    join public.subtopics s on s.id=c.subtopic_id
    where c.id=p_concept_id for update of c,t,s;
  if not found then return jsonb_build_object('error','concept_not_found'); end if;
  select t.is_active,s.is_active,s.slug into
    v_topic_active,v_subtopic_active,v_subtopic_slug
    from public.topics t join public.subtopics s on s.topic_id=t.id
    where s.id=v_concept.subtopic_id;
  v_snapshot := to_jsonb(v_concept)-array['created_at','published_at','status'];
  v_token := public.edge_api_editorial_concept_token(p_concept_id);
  if v_token<>p_expected_token then
    return jsonb_build_object('error','stale_revision');
  end if;
  v_note := regexp_replace(p_note,'^[[:space:]]+|[[:space:]]+$','','g');
  if length(v_note)<10 then
    return jsonb_build_object('error','review_conflict',
      'message','Record a substantive note of at least 10 characters');
  end if;
  if p_action='comment' then
    insert into public.editorial_workflow_events
      (concept_id,actor_id,registered_name,action,note,details)
      values(p_concept_id,p_user_id,v_actor->>'approved_name',
        'comment',v_note,'{}'::jsonb);
  elsif p_action='retire' then
    if v_concept.status not in ('published','draft') then
      return jsonb_build_object('error','review_conflict',
        'message','Only published content or a draft can be retired here');
    end if;
    update public.concepts set status='archived' where id=p_concept_id;
    insert into public.editorial_workflow_events
      (concept_id,actor_id,registered_name,action,note,details)
      values(p_concept_id,p_user_id,v_actor->>'approved_name',
        'content_retired',v_note,jsonb_build_object(
          'content_version',v_concept.content_version,'snapshot',v_snapshot));
  else
    if not coalesce(p_body_valid,false) then
      return jsonb_build_object('error','review_conflict',
        'message','Resolve the concept validation errors before attesting');
    end if;
    if v_concept.status<>'published' or not v_topic_active or not v_subtopic_active then
      return jsonb_build_object('error','review_conflict',
        'message','Choose the exact current published legacy version');
    end if;
    if not exists(select 1 from public.editorial_legacy_versions l
      where l.concept_id=p_concept_id and l.content_version=v_concept.content_version
        and l.snapshot=v_snapshot) then
      return jsonb_build_object('error','review_conflict',
        'message','Only the unchanged inventoried legacy version can be attested');
    end if;
    if exists(select 1 from public.editorial_publications p
      where p.concept_id=p_concept_id and p.content_version=v_concept.content_version) then
      return jsonb_build_object('error','review_conflict',
        'message','This version already has authenticated provenance');
    end if;
    v_body := jsonb_build_object(
      'title',v_concept.title,'summary',v_concept.summary,
      'example',v_concept.example,'subtopic_slug',v_subtopic_slug,
      'curriculum',v_concept.curriculum,
      'learning_package',jsonb_build_object(
        'flashcard',v_concept.flashcard,'mcqs',v_concept.mcqs),
      'model',v_concept.model,'prompt_version',v_concept.prompt_version);
    v_problem := public.edge_api_editorial_candidate_problem(
      p_concept_id,v_concept.slug,v_body);
    if v_problem is not null then
      return jsonb_build_object('error','review_conflict','message',v_problem);
    end if;
    insert into public.editorial_revision_events
      (revision_id,concept_id,base_version,actor_id,registered_name,action,
       revision_body,source_snapshot,note,checklist_version,quality_review)
      values(null,p_concept_id,v_concept.content_version,p_user_id,
        v_actor->>'approved_name','attested',v_body,v_snapshot,v_note,1,p_quality)
      returning id into v_event;
    insert into public.editorial_publications
      (concept_id,content_version,approval_id,snapshot)
      values(p_concept_id,v_concept.content_version,v_event,v_snapshot);
  end if;
  select c.* into v_concept from public.concepts c where c.id=p_concept_id;
  v_result := jsonb_build_object(
    'concept_id',p_concept_id,'status',v_concept.status,
    'content_version',v_concept.content_version,
    'token',public.edge_api_editorial_concept_token(p_concept_id));
  insert into public.editorial_request_receipts
    (actor_id,request_id,fingerprint,result)
    values(p_user_id,p_request_id,p_fingerprint,v_result);
  return v_result;
end
$function$

edge_api_editorial_concept_timeline.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_concept_timeline(p_user_id uuid, p_session_id uuid, p_aal text, p_concept_id uuid, p_after_at timestamp with time zone, p_after_key text, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_items jsonb;
  v_next text;
begin
  if p_limit is null or p_limit<1 or p_limit>100 then
    return jsonb_build_object('error','invalid_page');
  end if;
  if (p_after_at is null) <> (p_after_key is null)
    or (p_after_key is not null and p_after_key !~* '^[rw]:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then
    return jsonb_build_object('error','invalid_cursor');
  end if;
  v_actor := public.edge_api_editorial_authorize_any(
    p_user_id,p_session_id,p_aal,array['review','approve','publish']);
  if v_actor ? 'error' then return v_actor; end if;
  if p_concept_id is null or not exists(
    select 1 from public.concepts where id=p_concept_id
  ) then
    return jsonb_build_object('error','concept_not_found');
  end if;
  with events as (
    select 'r:'||e.id::text as id,e.revision_id,e.actor_id,
      e.registered_name,e.action,e.note,
      jsonb_build_object('base_version',e.base_version,
        'checklist_version',e.checklist_version,
        'quality_review',e.quality_review) as details,e.created_at
    from public.editorial_revision_events e where e.concept_id=p_concept_id
    union all
    select 'w:'||e.id::text,e.revision_id,e.actor_id,e.registered_name,
      e.action,e.note,e.details,e.created_at
    from public.editorial_workflow_events e where e.concept_id=p_concept_id
  ), page as (
    select *,row_number() over(order by created_at,id) as position
    from (select * from events
      where p_after_at is null or (created_at,id)>(p_after_at,p_after_key)
      order by created_at,id limit p_limit+1) bounded
  )
  select coalesce(jsonb_agg((to_jsonb(page)-'position') || jsonb_build_object(
    'created_at',public.edge_api_editorial_utc_iso(page.created_at))
    order by created_at,id)
           filter(where position<=p_limit),'[]'::jsonb),
         (select rtrim(translate(replace(encode(convert_to(
           format('["%s", "%s"]',
             public.edge_api_editorial_utc_iso(last.created_at),last.id),
             'UTF8'),'base64'),E'\n',''),'+/','-_'),'=')
          from page last where last.position=p_limit
            and exists(select 1 from page extra where extra.position>p_limit))
    into v_items,v_next from page;
  return jsonb_build_object('items',v_items,'next_cursor',v_next);
end
$function$

edge_api_editorial_create_legacy_batch.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_create_legacy_batch(p_user_id uuid, p_session_id uuid, p_aal text, p_topic_id uuid, p_request_id uuid, p_note text, p_name text, p_quota_limit integer, p_model text, p_configured boolean, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_receipt public.editorial_request_receipts%rowtype;
  v_batch_id uuid;
  v_count integer;
  v_result jsonb;
  v_note text;
begin
  if p_topic_id is null or p_request_id is null or p_note is null
    or length(p_note)<10 or length(p_note)>4000
    or p_name is null or p_name !~ '^[a-z0-9][a-z0-9-]{2,119}$'
    or p_quota_limit is null or p_quota_limit<1 or p_quota_limit>500
    or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('error','invalid');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  select * into v_receipt from public.editorial_request_receipts
    where actor_id=p_user_id and request_id=p_request_id;
  if found then
    if v_receipt.fingerprint<>p_fingerprint then
      return jsonb_build_object('error','receipt_conflict');
    end if;
    return v_receipt.result;
  end if;
  if not coalesce(p_configured,false) then
    return jsonb_build_object('error','legacy_disabled');
  end if;
  if p_model is null or p_model !~ '^gemini-3' then
    return jsonb_build_object('error','review_conflict','message',
      'Legacy grounding and structured output require a Gemini 3 model');
  end if;
  if exists(select 1 from public.editorial_legacy_batches
    where status in ('queued','running','paused')) then
    return jsonb_build_object('error','review_conflict','message',
      'Finish or cancel the active subject batch before selecting another');
  end if;
  if not exists(select 1 from public.topics
    where id=p_topic_id and is_active for update) then
    return jsonb_build_object('error','review_conflict','message',
      'Choose an active subject');
  end if;
  select count(*)::integer into v_count
    from public.concepts c join public.subtopics s on s.id=c.subtopic_id
    where c.topic_id=p_topic_id and c.status='published' and s.is_active
      and (not exists(select 1 from public.editorial_publications p
        where p.concept_id=c.id and p.content_version=c.content_version)
        or length(btrim(coalesce(c.curriculum->>'objective','')))=0
        or c.curriculum->'difficulty' is null
        or case when jsonb_typeof(c.curriculum->'references')='array'
          then jsonb_array_length(c.curriculum->'references')=0 else true end
        or length(btrim(coalesce(c.flashcard->>'front','')))=0
        or length(btrim(coalesce(c.flashcard->>'back','')))=0
        or case when jsonb_typeof(c.mcqs)='array'
          then jsonb_array_length(c.mcqs)<>3 else true end)
      and not exists(select 1 from public.concept_revisions r
        where r.concept_id=c.id and r.status in
          ('draft','generating','validation_failed','pending_review','changes_requested','approved'))
      and not exists(select 1 from public.editorial_legacy_batch_entries e
        where e.concept_id=c.id and e.status='ready_for_review');
  if v_count=0 then
    return jsonb_build_object('error','review_conflict','message',
      'This subject has no eligible published lessons to enrich');
  end if;
  if v_count>p_quota_limit then
    return jsonb_build_object('error','review_conflict','message',
      'Quota limit is below this subject’s eligible lesson count');
  end if;
  v_note := regexp_replace(p_note,'^[[:space:]]+|[[:space:]]+$','','g');
  if length(v_note)<10 then
    return jsonb_build_object('error','review_conflict','message',
      'Record a substantive note of at least 10 characters');
  end if;
  insert into public.editorial_legacy_batches
    (topic_id,name,requested_by,model,prompt_version,discovered_count,quota_limit)
    values(p_topic_id,p_name,p_user_id,p_model,
      'legacy-complete-card-v5-publication-bounds',v_count,p_quota_limit)
    returning id into v_batch_id;
  insert into public.editorial_legacy_batch_entries
    (batch_id,concept_id,base_version,source_body)
    select v_batch_id,c.id,c.content_version,jsonb_build_object(
      'title',c.title,'summary',c.summary,'example',c.example,
      'curriculum',c.curriculum,'flashcard',c.flashcard,'mcqs',c.mcqs,
      'topic_id',c.topic_id,'subtopic_id',c.subtopic_id,'subtopic_slug',s.slug)
    from public.concepts c join public.subtopics s on s.id=c.subtopic_id
    where c.topic_id=p_topic_id and c.status='published' and s.is_active
      and (not exists(select 1 from public.editorial_publications p
        where p.concept_id=c.id and p.content_version=c.content_version)
        or length(btrim(coalesce(c.curriculum->>'objective','')))=0
        or c.curriculum->'difficulty' is null
        or case when jsonb_typeof(c.curriculum->'references')='array'
          then jsonb_array_length(c.curriculum->'references')=0 else true end
        or length(btrim(coalesce(c.flashcard->>'front','')))=0
        or length(btrim(coalesce(c.flashcard->>'back','')))=0
        or case when jsonb_typeof(c.mcqs)='array'
          then jsonb_array_length(c.mcqs)<>3 else true end)
      and not exists(select 1 from public.concept_revisions r
        where r.concept_id=c.id and r.status in
          ('draft','generating','validation_failed','pending_review','changes_requested','approved'))
      and not exists(select 1 from public.editorial_legacy_batch_entries e
        where e.concept_id=c.id and e.status='ready_for_review')
    order by c.created_at,c.id;
  insert into public.editorial_workflow_events
    (topic_id,actor_id,registered_name,action,note,details)
    values(p_topic_id,p_user_id,v_actor->>'approved_name',
      'generation_requested',v_note,jsonb_build_object(
        'kind','legacy_enrichment','batch_id',v_batch_id,'eligible',v_count));
  select public.edge_api_editorial_legacy_batch_public(b) into v_result
    from public.editorial_legacy_batches b where id=v_batch_id;
  insert into public.editorial_request_receipts
    (actor_id,request_id,fingerprint,result)
    values(p_user_id,p_request_id,p_fingerprint,v_result);
  return v_result;
end
$function$

edge_api_editorial_generation_job.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_generation_job(p_user_id uuid, p_session_id uuid, p_aal text, p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_job public.editorial_generation_jobs%rowtype;
begin
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'review');
  if v_actor ? 'error' then return v_actor; end if;
  select * into v_job from public.editorial_generation_jobs where id=p_job_id;
  if not found then return jsonb_build_object('error','job_not_found'); end if;
  return public.edge_api_editorial_job_public(v_job);
end
$function$

edge_api_editorial_invite_finish.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_invite_finish(p_user_id uuid, p_session_id uuid, p_aal text, p_email text, p_invited_id uuid, p_capabilities text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_caps text[];
  v_count bigint;
begin
  if p_invited_id is null or p_email is null or length(p_email)>254
    or p_email<>lower(btrim(p_email))
    or p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    or p_capabilities is null or cardinality(p_capabilities)>5
    or array_position(p_capabilities,null) is not null
    or not (p_capabilities <@ array['review','approve','publish',
      'request_generation','manage_reviewers']::text[]) then
    return jsonb_build_object('error','invalid');
  end if;
  select coalesce(array_agg(cap order by cap),array[]::text[]) into v_caps
    from (select distinct unnest(p_capabilities) as cap) dedup;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  select count(*) into v_count from auth.users
    where lower(email)=p_email;
  if v_count>1 then return jsonb_build_object('error','duplicate_identity'); end if;
  if v_count=0 or not exists(select 1 from auth.users
      where id=p_invited_id and lower(email)=p_email) then
    return jsonb_build_object('error','identity_not_ready');
  end if;
  if exists(select 1 from public.editorial_memberships
      where user_id=p_invited_id) then
    return jsonb_build_object('error','reviewer_exists');
  end if;
  insert into public.editorial_memberships(user_id,invited_email,capabilities)
    values(p_invited_id,p_email,v_caps);
  insert into public.editorial_account_events(actor_id,subject_id,action,details)
    values(p_user_id,p_invited_id,'invite',
      jsonb_build_object('capabilities',v_caps));
  return (select to_jsonb(m) from public.editorial_memberships m
    where m.user_id=p_invited_id);
end
$function$

edge_api_editorial_invite_prepare.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_invite_prepare(p_user_id uuid, p_session_id uuid, p_aal text, p_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_count bigint;
  v_identity uuid;
begin
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  if p_email is null or length(p_email)>254 or p_email<>lower(btrim(p_email))
    or p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    return jsonb_build_object('error','invalid');
  end if;
  select count(*),min(id::text)::uuid into v_count,v_identity from auth.users
    where lower(email)=p_email;
  if v_count>1 then return jsonb_build_object('error','duplicate_identity'); end if;
  if v_identity is not null and exists(select 1 from public.editorial_memberships
    where user_id=v_identity) then
    return jsonb_build_object('error','reviewer_exists');
  end if;
  return jsonb_build_object('user_id',v_identity,
    'needs_invite',v_identity is null);
end
$function$

edge_api_editorial_legacy_batch_action.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_legacy_batch_action(p_user_id uuid, p_session_id uuid, p_aal text, p_batch_id uuid, p_request_id uuid, p_note text, p_expected_token text, p_action text, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_receipt public.editorial_request_receipts%rowtype;
  v_batch public.editorial_legacy_batches%rowtype;
  v_visible jsonb;
  v_note text;
  v_target text;
begin
  if p_batch_id is null or p_request_id is null or p_note is null
    or length(p_note)<10 or length(p_note)>4000
    or p_expected_token is null or p_expected_token !~ '^[a-f0-9]{64}$'
    or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$'
    or p_action is null or p_action not in ('pause','resume','cancel') then
    return jsonb_build_object('error','invalid');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  select * into v_receipt from public.editorial_request_receipts
    where actor_id=p_user_id and request_id=p_request_id;
  if found then
    if v_receipt.fingerprint<>p_fingerprint then
      return jsonb_build_object('error','receipt_conflict');
    end if;
    return v_receipt.result;
  end if;
  select * into v_batch from public.editorial_legacy_batches
    where id=p_batch_id for update;
  if not found then return jsonb_build_object('error','batch_not_found'); end if;
  v_visible := public.edge_api_editorial_legacy_batch_public(v_batch);
  if v_visible->>'token'<>p_expected_token then
    return jsonb_build_object('error','stale_revision');
  end if;
  if not ((p_action='pause' and v_batch.status in ('queued','running'))
    or (p_action='resume' and v_batch.status in ('queued','paused'))
    or (p_action='cancel' and v_batch.status in ('queued','running','paused'))) then
    return jsonb_build_object('error','review_conflict',
      'message','This batch cannot make that transition');
  end if;
  v_note := regexp_replace(p_note,'^[[:space:]]+|[[:space:]]+$','','g');
  if length(v_note)<10 then
    return jsonb_build_object('error','review_conflict',
      'message','Record a substantive note of at least 10 characters');
  end if;
  v_target := case p_action when 'pause' then 'paused'
    when 'resume' then 'running' else 'cancelled' end;
  update public.editorial_legacy_batches set status=v_target,
    started_at=coalesce(started_at,clock_timestamp()),
    finished_at=case when v_target='cancelled' then clock_timestamp() else null end
    where id=p_batch_id;
  if p_action='cancel' then
    update public.editorial_legacy_batch_entries set status='skipped',
      claim_token=null,claimed_at=null,failure_code='batch_cancelled',
      updated_at=clock_timestamp()
      where batch_id=p_batch_id and status in ('queued','generating');
  end if;
  insert into public.editorial_workflow_events
    (topic_id,actor_id,registered_name,action,note,details)
    values(v_batch.topic_id,p_user_id,v_actor->>'approved_name',
      'comment',v_note,jsonb_build_object('kind','legacy_enrichment',
        'batch_id',p_batch_id,'action',p_action));
  select public.edge_api_editorial_legacy_batch_public(b) into v_visible
    from public.editorial_legacy_batches b where id=p_batch_id;
  insert into public.editorial_request_receipts
    (actor_id,request_id,fingerprint,result)
    values(p_user_id,p_request_id,p_fingerprint,v_visible);
  return v_visible;
end
$function$

edge_api_editorial_legacy_batch_public.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_legacy_batch_public(p_batch public.editorial_legacy_batches)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_started text;
  v_finished text;
  v_payload text;
  v_counts jsonb;
begin
  v_started := public.edge_api_editorial_utc_iso(p_batch.started_at);
  v_finished := public.edge_api_editorial_utc_iso(p_batch.finished_at);
  -- The token uses Python's sorted, compact JSON encoding of the six version fields.
  v_payload := format(
    '{"discovered_count":%s,"finished_at":%s,"id":%s,"quota_limit":%s,"started_at":%s,"status":%s}',
    p_batch.discovered_count, coalesce(to_jsonb(v_finished)::text,'null'),
    to_jsonb(p_batch.id)::text, p_batch.quota_limit,
    coalesce(to_jsonb(v_started)::text,'null'), to_jsonb(p_batch.status)::text);
  select coalesce(jsonb_object_agg(s.status,s.total),'{}'::jsonb) into v_counts
  from (
    select case when e.status='ready_for_review' and r.status='published'
        then 'published' else e.status end as status, count(*)::integer as total
    from public.editorial_legacy_batch_entries e
    left join public.concept_revisions r on r.id=e.result_revision_id
    where e.batch_id=p_batch.id group by 1
  ) s;
  return jsonb_build_object(
    'id',p_batch.id,'topic_id',p_batch.topic_id,'name',p_batch.name,
    'model',p_batch.model,'prompt_version',p_batch.prompt_version,
    'status',p_batch.status,'discovered_count',p_batch.discovered_count,
    'quota_limit',p_batch.quota_limit,
    'created_at',public.edge_api_editorial_utc_iso(p_batch.created_at),
    'started_at',v_started,'finished_at',v_finished,
    'token',encode(pg_catalog.sha256(convert_to(v_payload,'UTF8')),'hex'),
    'counts',v_counts);
end
$function$

edge_api_editorial_legacy_batches.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_legacy_batches(p_user_id uuid, p_session_id uuid, p_aal text, p_topic_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_items jsonb;
begin
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'review');
  if v_actor ? 'error' then return v_actor; end if;
  select coalesce(jsonb_agg(public.edge_api_editorial_legacy_batch_public(b)
    order by b.created_at desc),'[]'::jsonb) into v_items
  from public.editorial_legacy_batches b
  where p_topic_id is null or b.topic_id=p_topic_id;
  return jsonb_build_object('items',v_items);
end
$function$

edge_api_editorial_legacy_entries.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_legacy_entries(p_user_id uuid, p_session_id uuid, p_aal text, p_batch_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_items jsonb;
begin
  v_actor := public.edge_api_editorial_authorize(
    p_user_id, p_session_id, p_aal, 'review');
  if v_actor ? 'error' then return v_actor; end if;
  if p_batch_id is null or not exists(
    select 1 from public.editorial_legacy_batches where id = p_batch_id
  ) then
    return jsonb_build_object('error', 'batch_not_found');
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', e.id, 'concept_id', e.concept_id, 'title', c.title,
    'base_version', e.base_version, 'attempts', e.attempts,
    'status', case when e.status = 'ready_for_review' and r.status = 'published'
      then 'published' else e.status end,
    'result_revision_id', e.result_revision_id, 'failure_code', e.failure_code
  ) order by e.created_at, e.id), '[]'::jsonb) into v_items
  from public.editorial_legacy_batch_entries e
  join public.concepts c on c.id = e.concept_id
  left join public.concept_revisions r on r.id = e.result_revision_id
  where e.batch_id = p_batch_id;
  return jsonb_build_object('items', v_items);
end
$function$

edge_api_editorial_me.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_me(p_user_id uuid, p_session_id uuid, p_aal text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_member public.editorial_memberships%rowtype;
begin
  if p_session_id is null or not exists(
    select 1 from auth.users u join auth.sessions s on s.user_id = u.id
     where u.id = p_user_id and s.id = p_session_id
       and u.email_confirmed_at is not null
       and (u.banned_until is null or u.banned_until <= statement_timestamp())
       and (s.not_after is null or s.not_after > statement_timestamp())
  ) then
    return jsonb_build_object('error', 'session_required');
  end if;
  select * into v_member from public.editorial_memberships
   where user_id = p_user_id and status = 'active';
  if not found then return jsonb_build_object('error', 'unavailable'); end if;
  return jsonb_build_object(
    'member', to_jsonb(v_member),
    'onboarding_required', v_member.requested_name is null,
    'name_approval_pending', v_member.requested_name is distinct from v_member.approved_name,
    'mfa_required', v_member.require_mfa and p_aal is distinct from 'aal2'
  );
end
$function$

edge_api_editorial_notification_policy.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_notification_policy(p_user_id uuid, p_session_id uuid, p_aal text, p_expected_version integer, p_deadline_hours integer, p_reminder_hours integer, p_max_reminders integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_version integer;
  v_result jsonb;
begin
  if p_expected_version is null or p_expected_version < 1
    or p_deadline_hours is null or p_deadline_hours not between 1 and 720
    or p_reminder_hours is null or p_reminder_hours not between 1 and 168
    or p_max_reminders is null or p_max_reminders not between 0 and 10 then
    return jsonb_build_object('error','invalid_policy');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  perform pg_catalog.pg_advisory_xact_lock(279,263);
  select version into v_version from public.editorial_notification_policy
    where singleton for update;
  if v_version is distinct from p_expected_version then
    return jsonb_build_object('error','policy_conflict');
  end if;
  update public.editorial_notification_policy set version=version+1,
    deadline_hours=p_deadline_hours,reminder_hours=p_reminder_hours,
    max_reminders=p_max_reminders where singleton;
  insert into public.editorial_account_events(actor_id,subject_id,action,details)
  values(p_user_id,p_user_id,'notification_policy',jsonb_build_object(
    'deadline_hours',p_deadline_hours,'reminder_hours',p_reminder_hours,
    'max_reminders',p_max_reminders));
  select to_jsonb(p) into v_result from public.editorial_notification_policy p
    where singleton;
  return v_result;
end
$function$

edge_api_editorial_notification_retry.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_notification_retry(p_user_id uuid, p_session_id uuid, p_aal text, p_batch_id uuid, p_expected_version integer, p_setup_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_batch public.editorial_email_batches%rowtype;
begin
  if p_batch_id is null or p_expected_version is null or p_expected_version < 1 then
    return jsonb_build_object('error','invalid');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  perform pg_catalog.pg_advisory_xact_lock(279,263);
  if p_setup_status is distinct from 'ready' then
    return jsonb_build_object('error','sender_setup_required');
  end if;
  select * into v_batch from public.editorial_email_batches
    where id=p_batch_id for update;
  if not found then return jsonb_build_object('error','delivery_not_found'); end if;
  if v_batch.attempts <> p_expected_version or v_batch.status <> 'failed'
    or v_batch.attempts >= 5 then
    return jsonb_build_object('error','delivery_conflict');
  end if;
  update public.editorial_email_batches set status='pending',available_at=now()
    where id=p_batch_id;
  insert into public.editorial_account_events(actor_id,subject_id,action,details)
  values(p_user_id,v_batch.recipient_id,'notification_retry',jsonb_build_object(
    'batch_id',p_batch_id::text,'attempts',v_batch.attempts));
  return jsonb_build_object('status','pending');
end
$function$

edge_api_editorial_notifications_overvie.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_notifications_overview(p_user_id uuid, p_session_id uuid, p_aal text, p_cursor uuid, p_limit integer, p_setup_status text, p_daily_cap integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_items jsonb;
  v_next uuid;
  v_counts jsonb;
  v_policy jsonb;
  v_overdue bigint;
  v_used bigint;
begin
  if p_limit is null or p_limit < 1 or p_limit > 100
    or p_daily_cap is null or p_daily_cap < 0 or p_daily_cap > 500
    or p_setup_status is null or p_setup_status not in (
      'disabled','dashboard_setup_required','sender_setup_required',
      'test_recipients_required','ready') then
    return jsonb_build_object('error','invalid_page');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  with page as (
    select b.id,jsonb_build_object(
      'id',b.id,'recipient_id',b.recipient_id,'status',b.status,
      'attempts',b.attempts,'failure_code',b.failure_code,
      'created_at',public.edge_api_editorial_utc_iso(b.created_at),
      'sent_at',public.edge_api_editorial_utc_iso(b.sent_at),
      'recipient_name',m.approved_name) as item
    from public.editorial_email_batches b
    left join public.editorial_memberships m on m.user_id=b.recipient_id
    where p_cursor is null or b.id>p_cursor
    order by b.id limit p_limit+1
  ), numbered as (
    select page.*,row_number() over(order by id) as position from page
  )
  select coalesce(jsonb_agg(item order by id) filter(where position<=p_limit),'[]'::jsonb),
    (select id from numbered where position=p_limit
      and exists(select 1 from numbered where position>p_limit))
    into v_items,v_next from numbered;
  select coalesce(jsonb_object_agg(s.status,s.total),'{}'::jsonb) into v_counts
    from (select status,count(*)::bigint as total
      from public.editorial_email_batches group by status) s;
  select to_jsonb(p) into v_policy from public.editorial_notification_policy p
    where singleton;
  select count(*) into v_overdue
    from public.concept_revisions r join public.concepts c on c.id=r.concept_id
    where r.status in ('draft','pending_review')
      and r.review_due_at<now() and r.base_version=c.content_version
      and c.status<>'archived';
  select count(*) into v_used from public.editorial_email_attempts
    where started_at>now()-interval '24 hours';
  return jsonb_build_object(
    'policy',v_policy,'setup_status',p_setup_status,'daily_cap',p_daily_cap,
    'attempts_last_24h',v_used,'overdue',v_overdue,'counts',v_counts,
    'items',v_items,'next_cursor',v_next);
end
$function$

edge_api_editorial_owner_events.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_owner_events(p_user_id uuid, p_session_id uuid, p_aal text, p_start date, p_end date, p_source text, p_severity text, p_search text, p_correlation uuid, p_before_time timestamp with time zone, p_before_key text, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_window jsonb;
  v_start timestamptz;
  v_stop timestamptz;
  v_items jsonb := '[]'::jsonb;
  v_next text;
  v_count integer := 0;
  v_has_more boolean := false;
  v_row record;
begin
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  if p_limit is null or p_limit<1 or p_limit>50 or length(p_search)>80
    or (p_source is not null and p_source not in
      ('api','reminders','pool_topup','review','workflow','account'))
    or (p_severity is not null and p_severity not in ('info','error')) then
    return jsonb_build_object('error','invalid_page');
  end if;
  if (p_before_time is null) <> (p_before_key is null)
    or length(p_before_key)>80 then
    return jsonb_build_object('error','invalid_cursor');
  end if;
  v_window := public.edge_api_editorial_owner_window(p_start,p_end);
  if v_window ? 'error' then return v_window; end if;
  perform pg_catalog.set_config('statement_timeout','5s',true);
  perform pg_catalog.set_config('TimeZone','UTC',true);
  v_start := (v_window->>'start')::timestamptz;
  v_stop := (v_window->>'stop')::timestamptz;
  for v_row in
    with events as (
      select 'operation:'||id::text as key,observed_at,
        service as source,code as action,severity,correlation_id
        from public.owner_operation_events
        where observed_at>=v_start and observed_at<v_stop
          and observed_at>=now()-interval '30 days'
      union all
      select 'review:'||id::text,created_at,'review',action,
        case when action='validation_failed' then 'error' else 'info' end,id
        from public.editorial_revision_events
        where created_at>=v_start and created_at<v_stop
      union all
      select 'workflow:'||id::text,created_at,'workflow',action,'info',id
        from public.editorial_workflow_events
        where created_at>=v_start and created_at<v_stop
      union all
      select 'account:'||id::text,created_at,'account',action,'info',null::uuid
        from public.editorial_account_events
        where created_at>=v_start and created_at<v_stop
    )
    select * from events
      where (p_source is null or source=p_source)
        and (p_severity is null or severity=p_severity)
        and (p_correlation is null or correlation_id=p_correlation)
        and (p_search is null or strpos(lower(source||' '||action),lower(p_search))>0)
        and (p_before_time is null or (observed_at,key)<(p_before_time,p_before_key))
      order by observed_at desc,key desc limit p_limit+1
  loop
    if v_count>=p_limit then
      v_has_more := true;
      exit;
    end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'key',v_row.key,
      'observed_at',public.edge_api_editorial_utc_iso(v_row.observed_at),
      'source',v_row.source,'action',v_row.action,
      'severity',v_row.severity,'correlation_id',v_row.correlation_id));
    v_count := v_count+1;
    v_next := public.edge_api_editorial_utc_iso(v_row.observed_at)||'~'||v_row.key;
  end loop;
  return jsonb_build_object(
    'items',v_items,'next_cursor',case when v_has_more then v_next else null end,
    'observed_at',v_window->>'observed_at');
end
$function$

edge_api_editorial_owner_operations.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_owner_operations(p_user_id uuid, p_session_id uuid, p_aal text, p_environment text, p_telemetry_enabled boolean, p_generation_enabled boolean, p_future_refill_enabled boolean, p_legacy_enrichment_enabled boolean, p_auto_correction_enabled boolean, p_email_enabled boolean, p_generation_daily_cap integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_now timestamptz := clock_timestamp();
  v_workers jsonb := '[]'::jsonb;
  v_service text;
  v_stale_minutes integer;
  v_event record;
  v_observation jsonb;
  v_status text;
  v_budget bigint;
  v_jobs jsonb;
  v_emails jsonb;
begin
  if p_environment is null or length(p_environment)>40
    or p_telemetry_enabled is null or p_generation_enabled is null
    or p_future_refill_enabled is null or p_legacy_enrichment_enabled is null
    or p_auto_correction_enabled is null or p_email_enabled is null
    or p_generation_daily_cap is null or p_generation_daily_cap<0 then
    return jsonb_build_object('error','invalid_config');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.set_config('statement_timeout','5s',true);
  perform pg_catalog.set_config('TimeZone','UTC',true);
  for v_service,v_stale_minutes in
    select * from (values ('reminders',45),('pool_topup',2160)) as services(service,minutes)
  loop
    select observed_at,code,correlation_id into v_event
      from public.owner_operation_events
      where service=v_service and observed_at>=v_now-interval '30 days'
      order by observed_at desc,id desc limit 1;
    if found then
      v_observation := jsonb_build_object(
        'observed_at',public.edge_api_editorial_utc_iso(v_event.observed_at),
        'code',v_event.code,'correlation_id',v_event.correlation_id);
      v_status := case when extract(epoch from (v_now-v_event.observed_at))/60 >
        case when v_event.code='started' then 30 else v_stale_minutes end
        then 'stale' else v_event.code end;
    else
      v_observation := null;
      v_status := 'unavailable';
    end if;
    v_workers := v_workers || jsonb_build_array(jsonb_build_object(
      'service',v_service,'status',v_status,'observation',v_observation,
      'stale_after_minutes',v_stale_minutes));
  end loop;
  select coalesce((select calls_used from public.generation_daily_usage
    where budget_day=(statement_timestamp() at time zone 'America/Los_Angeles')::date),0)
    into v_budget;
  select jsonb_build_object(
    'pending',count(*) filter(where status='pending'),
    'generating',count(*) filter(where status='generating'),
    'failed',count(*) filter(where status='failed'),
    'stale',count(*) filter(where status='generating' and claimed_at<now()-interval '30 minutes'))
    into v_jobs from public.editorial_generation_jobs;
  select jsonb_build_object(
    'pending',count(*) filter(where status='pending'),
    'sending',count(*) filter(where status='sending'),
    'failed',count(*) filter(where status='failed'),
    'sent_last_day',count(*) filter(where status='sent' and sent_at>=now()-interval '24 hours'))
    into v_emails from public.editorial_email_batches;
  return jsonb_build_object(
    'observed_at',public.edge_api_editorial_utc_iso(v_now),
    'environment',p_environment,'api','reachable','database','reachable',
    'telemetry_enabled',p_telemetry_enabled,
    'generation_enabled',p_generation_enabled,
    'future_refill_enabled',p_generation_enabled and p_future_refill_enabled,
    'legacy_enrichment_enabled',p_generation_enabled and p_legacy_enrichment_enabled,
    'editorial_auto_correction_enabled',p_generation_enabled and p_auto_correction_enabled,
    'email_enabled',p_email_enabled,
    'workers',v_workers,'revision_jobs',v_jobs,'emails',v_emails,
    'budget',jsonb_build_object(
      'reserved_calls',v_budget,'configured_cap',p_generation_daily_cap,
      'timezone','America/Los_Angeles'),
    'unavailable',jsonb_build_array(
      'Host CPU and memory','Provider delivery/inbox logs',
      'Historical uptime and request latency'));
end
$function$

edge_api_editorial_owner_overview.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_owner_overview(p_user_id uuid, p_session_id uuid, p_aal text, p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_window jsonb;
  v_start timestamptz;
  v_stop timestamptz;
  v_end date;
  v_month timestamptz;
  v_week timestamptz;
  v_day timestamptz;
  v_metrics jsonb;
  v_trend jsonb;
  v_team jsonb;
  v_queue jsonb;
begin
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  v_window := public.edge_api_editorial_owner_window(p_start,p_end);
  if v_window ? 'error' then return v_window; end if;
  perform pg_catalog.set_config('statement_timeout','5s',true);
  perform pg_catalog.set_config('TimeZone','UTC',true);
  v_start := (v_window->>'start')::timestamptz;
  v_stop := (v_window->>'stop')::timestamptz;
  v_end := (v_window->>'end')::date;
  v_month := (v_end-29)::timestamp at time zone 'UTC';
  v_week := (v_end-6)::timestamp at time zone 'UTC';
  v_day := v_end::timestamp at time zone 'UTC';
  with learners as (
    select p.id,p.created_at from public.profiles p where p.created_at<v_stop and (
      not exists(select 1 from public.editorial_memberships m where m.user_id=p.id)
      or exists(select 1 from public.user_concept_completions x
        where x.user_id=p.id and x.completed_at<v_stop)
      or exists(select 1 from public.daily_reviews x
        where x.user_id=p.id and x.completed_at<v_stop))
  ), activity as (
    select user_id,completed_at,'lesson' as kind
      from public.user_concept_completions
      where completed_at>=least(v_start,v_month) and completed_at<v_stop
    union all
    select user_id,completed_at,'review' from public.daily_reviews
      where completed_at>=least(v_start,v_month) and completed_at<v_stop
  ), valid as (select a.* from activity a join learners l on l.id=a.user_id)
  select jsonb_build_object(
    'registered',(select count(*) from learners),
    'new_registrations',(select count(*) from learners where created_at>=v_start),
    'active_day',count(distinct user_id) filter(where completed_at>=v_day),
    'active_week',count(distinct user_id) filter(where completed_at>=v_week),
    'active_month',count(distinct user_id) filter(where completed_at>=v_month),
    'lessons',count(*) filter(where kind='lesson' and completed_at>=v_start),
    'reviews',count(*) filter(where kind='review' and completed_at>=v_start))
    into v_metrics from valid;
  with learners as (
    select p.id,p.created_at from public.profiles p where p.created_at<v_stop and (
      not exists(select 1 from public.editorial_memberships m where m.user_id=p.id)
      or exists(select 1 from public.user_concept_completions x
        where x.user_id=p.id and x.completed_at<v_stop)
      or exists(select 1 from public.daily_reviews x
        where x.user_id=p.id and x.completed_at<v_stop))
  ), activity as (
    select user_id,completed_at,'lesson' as kind
      from public.user_concept_completions where completed_at>=v_start and completed_at<v_stop
    union all
    select user_id,completed_at,'review' from public.daily_reviews
      where completed_at>=v_start and completed_at<v_stop
  ), daily as (
    select (completed_at at time zone 'UTC')::date as day,
      count(*) filter(where kind='lesson') as lessons,
      count(*) filter(where kind='review') as reviews,
      count(distinct user_id) as active
    from activity join learners on learners.id=activity.user_id group by 1
  ), days as (
    select d::date as day,coalesce(lessons,0) as lessons,
      coalesce(reviews,0) as reviews,coalesce(active,0) as active
    from generate_series(v_start,v_end::timestamp at time zone 'UTC',interval '1 day') d
    left join daily on daily.day=d::date
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'day',day,'lessons',lessons,'reviews',reviews,'active',active)
    order by day),'[]'::jsonb) into v_trend from days;
  select jsonb_build_object(
    'invited',count(*) filter(where status='active' and approved_name is null),
    'active',count(*) filter(where status='active' and approved_name is not null),
    'revoked',count(*) filter(where status='revoked')) into v_team
    from public.editorial_memberships;
  select jsonb_build_object(
    'pending',count(*),
    'assigned',count(*) filter(where assigned_to is not null),
    'overdue',count(*) filter(where review_due_at<statement_timestamp()))
    into v_queue from public.concept_revisions r join public.concepts c on c.id=r.concept_id
    where r.status in ('draft','pending_review','changes_requested','validation_failed','approved')
      and r.base_version=c.content_version and c.status<>'archived';
  return v_window || jsonb_build_object(
    'metrics',v_metrics,'trend',v_trend,'team',v_team,'queue',v_queue);
end
$function$

edge_api_editorial_owner_reviewers.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_owner_reviewers(p_user_id uuid, p_session_id uuid, p_aal text, p_start date, p_end date, p_cursor uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_window jsonb;
  v_start timestamptz;
  v_stop timestamptz;
  v_items jsonb := '[]'::jsonb;
  v_next uuid;
  v_count integer := 0;
  v_has_more boolean := false;
  v_row record;
begin
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  if p_limit is null or p_limit<1 or p_limit>50 then
    return jsonb_build_object('error','invalid_page');
  end if;
  v_window := public.edge_api_editorial_owner_window(p_start,p_end);
  if v_window ? 'error' then return v_window; end if;
  perform pg_catalog.set_config('statement_timeout','5s',true);
  perform pg_catalog.set_config('TimeZone','UTC',true);
  v_start := (v_window->>'start')::timestamptz;
  v_stop := (v_window->>'stop')::timestamptz;
  for v_row in
    with identities as (
      select user_id as id from public.editorial_memberships
      union select actor_id from public.editorial_revision_events
        where created_at>=v_start and created_at<v_stop
      union select e.actor_id from public.editorial_publications p
        join public.editorial_revision_events e on e.id=p.approval_id
        where p.recorded_at>=v_start and p.recorded_at<v_stop
    ), page as (
      select id from identities where p_cursor is null or id>p_cursor
        order by id limit p_limit+1
    ), evidence as (
      select e.* from public.editorial_revision_events e
        join page on page.id=e.actor_id
        where e.created_at>=v_start and e.created_at<v_stop
    ), counts as (
      select actor_id,
        count(*) filter(where action in ('approved','attested')) as approval_events,
        count(distinct concept_id) filter(where action in ('approved','attested')) as approved_concepts,
        count(*) filter(where action='rejected') as rejections,
        count(*) filter(where action='changes_requested') as changes_requested
        from evidence group by actor_id
    ), published as (
      select e.actor_id,count(distinct p.concept_id) as published_concepts
        from public.editorial_publications p
        join public.editorial_revision_events e on e.id=p.approval_id
        join page on page.id=e.actor_id
        where p.recorded_at>=v_start and p.recorded_at<v_stop
        group by e.actor_id
    ), work as (
      select assigned_to,count(*) as pending,
        count(*) filter(where review_due_at<statement_timestamp()) as overdue
        from public.concept_revisions r
        join public.concepts c on c.id=r.concept_id
        join page on page.id=r.assigned_to
        where r.status in ('draft','pending_review','changes_requested',
          'validation_failed','approved') and r.base_version=c.content_version
          and c.status<>'archived' group by assigned_to
    )
    select page.id,
      coalesce(signature.registered_name,m.approved_name,'Name pending') as name,
      signature.created_at as signature_at,
      coalesce(m.status,'deleted') as status,
      coalesce(approval_events,0) as approval_events,
      coalesce(approved_concepts,0) as approved_concepts,
      coalesce(published_concepts,0) as published_concepts,
      coalesce(rejections,0) as rejections,
      coalesce(changes_requested,0) as changes_requested,
      coalesce(pending,0) as pending,coalesce(overdue,0) as overdue
      from page left join public.editorial_memberships m on m.user_id=page.id
      left join counts on counts.actor_id=page.id
      left join published on published.actor_id=page.id
      left join work on work.assigned_to=page.id
      left join lateral (
        select registered_name,created_at from public.editorial_revision_events e
          where actor_id=page.id and created_at<v_stop
          order by created_at desc,id desc limit 1
      ) signature on true order by page.id
  loop
    if v_count>=p_limit then
      v_has_more := true;
      exit;
    end if;
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'id',v_row.id,'name',v_row.name,
      'signature_at',case when v_row.signature_at is null then null
        else public.edge_api_editorial_utc_iso(v_row.signature_at) end,
      'status',v_row.status,'approval_events',v_row.approval_events,
      'approved_concepts',v_row.approved_concepts,
      'published_concepts',v_row.published_concepts,
      'rejections',v_row.rejections,
      'changes_requested',v_row.changes_requested,
      'pending',v_row.pending,'overdue',v_row.overdue));
    v_count := v_count+1;
    v_next := v_row.id;
  end loop;
  return jsonb_build_object(
    'items',v_items,'next_cursor',case when v_has_more then v_next else null end,
    'observed_at',v_window->>'observed_at');
end
$function$

edge_api_editorial_owner_window.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_owner_window(p_start date, p_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_today date;
  v_start date;
  v_end date;
  v_stop timestamptz;
begin
  v_today := (v_now at time zone 'UTC')::date;
  v_end := coalesce(p_end,v_today);
  if v_end < date '0001-01-30' then
    return jsonb_build_object('error','invalid_end');
  end if;
  v_start := coalesce(p_start,v_end-29);
  if v_end>v_today or v_start>v_end or v_end-v_start>89 then
    return jsonb_build_object('error','invalid_range');
  end if;
  v_stop := least((v_end+1)::timestamp at time zone 'UTC',v_now);
  return jsonb_build_object(
    'start',public.edge_api_editorial_utc_iso(v_start::timestamp at time zone 'UTC'),
    'stop',public.edge_api_editorial_utc_iso(v_stop),
    'end',v_end,'observed_at',public.edge_api_editorial_utc_iso(v_now));
end
$function$

edge_api_editorial_python_json.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_python_json(p_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_kind text := jsonb_typeof(p_value);
  v_result text;
  v_text text;
  v_char text;
  v_code integer;
  v_high integer;
  v_low integer;
  v_key text;
  v_item jsonb;
  v_first boolean;
  v_index integer;
begin
  if v_kind is null or v_kind='null' then return 'null'; end if;
  if v_kind in ('boolean','number') then return p_value::text; end if;
  if v_kind='string' then
    v_text := p_value #>> '{}';
    v_result := '"';
    for v_index in 1..char_length(v_text) loop
      v_char := substr(v_text,v_index,1);
      v_code := ascii(v_char);
      if v_code=34 or v_code=92 then
        v_result := v_result||chr(92)||v_char;
      elsif v_code=8 then v_result := v_result||chr(92)||'b';
      elsif v_code=9 then v_result := v_result||chr(92)||'t';
      elsif v_code=10 then v_result := v_result||chr(92)||'n';
      elsif v_code=12 then v_result := v_result||chr(92)||'f';
      elsif v_code=13 then v_result := v_result||chr(92)||'r';
      elsif v_code<32 or v_code>126 then
        if v_code<=65535 then
          v_result := v_result||chr(92)||'u'||lpad(to_hex(v_code),4,'0');
        else
          v_code := v_code-65536;
          v_high := 55296+v_code/1024;
          v_low := 56320+v_code%1024;
          v_result := v_result||chr(92)||'u'||lpad(to_hex(v_high),4,'0')
            ||chr(92)||'u'||lpad(to_hex(v_low),4,'0');
        end if;
      else v_result := v_result||v_char;
      end if;
    end loop;
    return v_result||'"';
  end if;
  if v_kind='array' then
    v_result := '[';
    v_first := true;
    for v_item in select value from jsonb_array_elements(p_value) loop
      if not v_first then v_result := v_result||','; end if;
      v_result := v_result||public.edge_api_editorial_python_json(v_item);
      v_first := false;
    end loop;
    return v_result||']';
  end if;
  v_result := '{';
  v_first := true;
  for v_key,v_item in select key,value from jsonb_each(p_value)
    order by key collate "C" loop
    if not v_first then v_result := v_result||','; end if;
    v_result := v_result||public.edge_api_editorial_python_json(to_jsonb(v_key))
      ||':'||public.edge_api_editorial_python_json(v_item);
    v_first := false;
  end loop;
  return v_result||'}';
end
$function$

edge_api_editorial_request_generation.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_request_generation(p_user_id uuid, p_session_id uuid, p_aal text, p_topic_id uuid, p_request_id uuid, p_note text, p_count integer, p_enabled boolean, p_review_limit integer, p_batch_limit integer, p_active_days integer, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_receipt public.editorial_request_receipts%rowtype;
  v_planned integer;
  v_inventory integer;
  v_load integer;
  v_slots integer;
  v_count integer;
  v_target integer;
  v_event uuid;
  v_result jsonb;
  v_note text;
begin
  if p_topic_id is null or p_request_id is null or p_note is null
    or length(p_note)<10 or length(p_note)>4000
    or p_count is null or p_count<1 or p_count>10
    or p_review_limit is null or p_review_limit<1 or p_review_limit>250
    or p_batch_limit is null or p_batch_limit<1 or p_batch_limit>25
    or p_active_days is null or p_active_days<1 or p_active_days>365
    or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('error','invalid');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  select * into v_receipt from public.editorial_request_receipts
    where actor_id=p_user_id and request_id=p_request_id;
  if found then
    if v_receipt.fingerprint<>p_fingerprint then
      return jsonb_build_object('error','receipt_conflict');
    end if;
    return v_receipt.result;
  end if;
  if not coalesce(p_enabled,false) then
    return jsonb_build_object('error','generation_disabled');
  end if;
  if not exists(select 1 from public.topics
    where id=p_topic_id and is_active) then
    return jsonb_build_object('error','review_conflict','message',
      'Choose an active topic');
  end if;
  select count(*)::integer into v_planned
    from public.concept_backlog b join public.subtopics s on s.id=b.subtopic_id
    where b.topic_id=p_topic_id and b.status='pending' and s.is_active
      and b.attempts<3+(select count(*) from public.content_retry_log l
        where l.backlog_id=b.id);
  if v_planned=0 then
    return jsonb_build_object('error','review_conflict','message',
      'No pending curriculum is available; plan lessons before requesting generation');
  end if;
  select count(*)::integer into v_inventory
    from public.concepts c join public.subtopics s
      on s.id=c.subtopic_id and s.is_active
    where c.topic_id=p_topic_id and c.status in ('published','draft');
  select (
    select count(*) from public.concepts c
      join public.subtopics s on s.id=c.subtopic_id
      where c.topic_id=p_topic_id and s.is_active and
        (c.status='draft' or (c.status='published' and exists(
          select 1 from public.concept_revisions r
          where r.concept_id=c.id and r.base_version=c.content_version
            and r.status in ('draft','generating','validation_failed',
              'pending_review','changes_requested','approved'))))
  ) + (
    select count(*) from public.concept_backlog b
      join public.subtopics s on s.id=b.subtopic_id
      where b.topic_id=p_topic_id and s.is_active and b.status='generating'
  ) into v_load;
  v_slots := greatest(0,p_review_limit-v_load);
  if v_slots=0 then
    return jsonb_build_object('error','review_conflict','message',
      'Review backlog is full; review or archive existing drafts first');
  end if;
  v_note := regexp_replace(p_note,'^[[:space:]]+|[[:space:]]+$','','g');
  if length(v_note)<10 then
    return jsonb_build_object('error','review_conflict','message',
      'Record a substantive note of at least 10 characters');
  end if;
  v_count := least(p_count,v_planned,p_batch_limit,v_slots);
  insert into public.content_supply_targets(topic_id,target_count,expires_at)
    values(p_topic_id,v_inventory+v_count,
      now()+make_interval(days=>p_active_days))
    on conflict(topic_id) do update set
      target_count=greatest(excluded.target_count,
        case when public.content_supply_targets.expires_at>now()
          then public.content_supply_targets.target_count else 0 end),
      requested_at=now(),expires_at=excluded.expires_at
    returning target_count into v_target;
  insert into public.editorial_workflow_events
    (topic_id,actor_id,registered_name,action,note,details)
    values(p_topic_id,p_user_id,v_actor->>'approved_name',
      'generation_requested',v_note,jsonb_build_object(
        'requested_count',p_count,'bounded_count',v_count,'target',v_target))
    returning id into v_event;
  v_result := jsonb_build_object('event_id',v_event,
    'status','demand_recorded','target',v_target);
  insert into public.editorial_request_receipts
    (actor_id,request_id,fingerprint,result)
    values(p_user_id,p_request_id,p_fingerprint,v_result);
  return v_result;
end
$function$

edge_api_editorial_reviewer_access.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_reviewer_access(p_user_id uuid, p_session_id uuid, p_aal text, p_subject_id uuid, p_expected_version integer, p_status text, p_capabilities text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_subject public.editorial_memberships%rowtype;
  v_caps text[];
  v_another boolean;
begin
  if p_subject_id is null or p_expected_version is null or p_expected_version<1
    or p_status is null or p_status not in ('active','revoked')
    or p_capabilities is null or cardinality(p_capabilities)>5
    or array_position(p_capabilities,null) is not null
    or not (p_capabilities <@ array['review','approve','publish',
      'request_generation','manage_reviewers']::text[]) then
    return jsonb_build_object('error','invalid');
  end if;
  select coalesce(array_agg(cap order by cap),array[]::text[]) into v_caps
    from (select distinct unnest(p_capabilities) as cap) dedup;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'manage_reviewers');
  if v_actor ? 'error' then return v_actor; end if;
  select * into v_subject from public.editorial_memberships
    where user_id=p_subject_id for update;
  if not found then return jsonb_build_object('error','unavailable'); end if;
  if v_subject.version<>p_expected_version then
    return jsonb_build_object('error','version_conflict');
  end if;
  if 'manage_reviewers'=any(v_subject.capabilities)
    and v_subject.status='active'
    and (p_status='revoked' or not 'manage_reviewers'=any(v_caps)) then
    select exists(select 1 from public.editorial_memberships m
      join auth.users u on u.id=m.user_id
      where m.user_id<>p_subject_id and m.status='active'
        and m.approved_name is not null
        and 'manage_reviewers'=any(m.capabilities)
        and u.email_confirmed_at is not null
        and (u.banned_until is null or u.banned_until<=now())) into v_another;
    if not v_another then return jsonb_build_object('error','last_admin'); end if;
  end if;
  if v_subject.status=p_status and (
    select coalesce(array_agg(distinct cap order by cap),array[]::text[])
      from unnest(v_subject.capabilities) cap
  ) = v_caps then
    return to_jsonb(v_subject);
  end if;
  update public.editorial_memberships set status=p_status,
    capabilities=v_caps,version=version+1,updated_at=now()
    where user_id=p_subject_id;
  insert into public.editorial_account_events(actor_id,subject_id,action,details)
    values(p_user_id,p_subject_id,'access_changed',jsonb_build_object(
      'previous_status',v_subject.status,'status',p_status,
      'previous_capabilities',v_subject.capabilities,
      'capabilities',v_caps,'version',v_subject.version+1));
  return (select to_jsonb(m) from public.editorial_memberships m
    where m.user_id=p_subject_id);
end
$function$

edge_api_editorial_revision_action.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_revision_action(p_user_id uuid, p_session_id uuid, p_aal text, p_revision_id uuid, p_request_id uuid, p_note text, p_expected_token text, p_action text, p_quality jsonb, p_assignee_id uuid, p_due_at timestamp with time zone, p_has_due boolean, p_body_valid boolean, p_auto_correction boolean, p_generation_enabled boolean, p_queue_limit integer, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_capability text;
  v_receipt public.editorial_request_receipts%rowtype;
  v_revision public.concept_revisions%rowtype;
  v_concept public.concepts%rowtype;
  v_assignee public.editorial_memberships%rowtype;
  v_approval public.editorial_revision_events%rowtype;
  v_topic_active boolean;
  v_subtopic_active boolean;
  v_subtopic_slug text;
  v_snapshot jsonb;
  v_status text;
  v_note text;
  v_problem text;
  v_event uuid;
  v_request_event uuid;
  v_version integer;
  v_generation_status text;
  v_source_token text;
  v_result jsonb;
begin
  if p_revision_id is null or p_request_id is null or p_note is null
    or length(p_note)<10 or length(p_note)>4000
    or p_expected_token is null or p_expected_token !~ '^[a-f0-9]{64}$'
    or p_action is null or p_action not in
      ('submit','comment','assign','changes_requested','rejected',
       'approved','publish','approve_and_publish','retired')
    or ((p_action in ('approved','approve_and_publish')) is distinct from
      (p_quality is not null))
    or (p_quality is not null and not coalesce(
      public.edge_api_editorial_quality_valid(p_quality),false))
    or (p_action<>'assign' and (p_assignee_id is not null or coalesce(p_has_due,false)))
    or p_queue_limit is null or p_queue_limit<1 or p_queue_limit>250
    or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('error','invalid');
  end if;
  v_capability := case
    when p_action in ('approved','approve_and_publish','retired') then 'approve'
    when p_action='publish' then 'publish'
    when p_action='assign' then 'manage_reviewers'
    else 'review' end;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,v_capability);
  if v_actor ? 'error' then return v_actor; end if;
  if p_action='approve_and_publish' then
    v_actor := public.edge_api_editorial_authorize(
      p_user_id,p_session_id,p_aal,'publish');
    if v_actor ? 'error' then return v_actor; end if;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,v_capability);
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,v_capability);
  if v_actor ? 'error' then return v_actor; end if;
  if p_action='approve_and_publish' then
    v_actor := public.edge_api_editorial_authorize(
      p_user_id,p_session_id,p_aal,'publish');
    if v_actor ? 'error' then return v_actor; end if;
  end if;
  select * into v_receipt from public.editorial_request_receipts
    where actor_id=p_user_id and request_id=p_request_id;
  if found then
    if v_receipt.fingerprint<>p_fingerprint then
      return jsonb_build_object('error','receipt_conflict');
    end if;
    return v_receipt.result;
  end if;
  select r.* into v_revision from public.concept_revisions r
    where r.id=p_revision_id for update;
  if not found then return jsonb_build_object('error','revision_not_found'); end if;
  select c.* into v_concept from public.concepts c
    join public.topics t on t.id=c.topic_id
    join public.subtopics s on s.id=c.subtopic_id
    where c.id=v_revision.concept_id for update of c,t,s;
  select t.is_active,s.is_active,s.slug into
    v_topic_active,v_subtopic_active,v_subtopic_slug
    from public.topics t join public.subtopics s on s.topic_id=t.id
    where s.id=v_concept.subtopic_id;
  v_snapshot := to_jsonb(v_concept)-array['created_at','published_at','status'];
  if public.edge_api_editorial_revision_token(p_revision_id)<>p_expected_token then
    return jsonb_build_object('error','stale_revision');
  end if;
  if v_revision.status='generating' then
    return jsonb_build_object('error','review_conflict',
      'message','Generation is still running; reload when the draft is ready');
  end if;
  v_note := regexp_replace(p_note,'^[[:space:]]+|[[:space:]]+$','','g');
  if length(v_note)<10 then
    return jsonb_build_object('error','review_conflict',
      'message','Record a substantive review note (at least 10 characters)');
  end if;
  if p_action in ('submit','assign','approved','changes_requested',
    'rejected','publish','approve_and_publish') and
    not (p_action='publish' and v_revision.status='published') and
    (v_revision.base_version<>v_concept.content_version
      or v_concept.status='archived' or not v_topic_active
      or not v_subtopic_active) then
    return jsonb_build_object('error','review_conflict',
      'message','Revision is stale or content is retired');
  end if;

  if p_action='submit' then
    if v_revision.status<>'draft' then
      return jsonb_build_object('error','review_conflict',
        'message','Only a new draft can be submitted; corrections need a new revision');
    end if;
    v_status := case when coalesce(p_body_valid,false)
      and v_revision.body->>'subtopic_slug'=v_subtopic_slug
      then 'pending_review' else 'validation_failed' end;
    insert into public.editorial_revision_events
      (revision_id,concept_id,base_version,actor_id,registered_name,action,
       revision_body,source_snapshot,note)
      values(p_revision_id,v_revision.concept_id,v_revision.base_version,p_user_id,
        v_actor->>'approved_name',v_status,v_revision.body,v_snapshot,v_note);
    update public.concept_revisions set status=v_status where id=p_revision_id;
  elsif p_action in ('approved','changes_requested','rejected','retired',
    'approve_and_publish') then
    if (p_action='retired' and v_revision.status not in
      ('draft','validation_failed','pending_review','changes_requested',
       'approved','rejected')) or
      (p_action<>'retired' and v_revision.status<>'pending_review') then
      return jsonb_build_object('error','review_conflict',
        'message','Invalid revision transition; reload before reviewing');
    end if;
    if p_action in ('approved','approve_and_publish') and
      (not coalesce(p_body_valid,false) or
        v_revision.body->>'subtopic_slug' is distinct from v_subtopic_slug) then
      return jsonb_build_object('error','review_conflict',
        'message','Approval requires matching taxonomy and the complete quality checklist');
    end if;
    if p_action='approve_and_publish' then
      v_problem := public.edge_api_editorial_candidate_problem(
        v_concept.id,v_concept.slug,v_revision.body);
      if v_problem is not null then
        return jsonb_build_object('error','review_conflict','message',v_problem);
      end if;
    end if;
    v_status := case when p_action='approve_and_publish' then 'approved'
      else p_action end;
    insert into public.editorial_revision_events
      (revision_id,concept_id,base_version,actor_id,registered_name,action,
       revision_body,source_snapshot,note,checklist_version,quality_review)
      values(p_revision_id,v_revision.concept_id,v_revision.base_version,p_user_id,
        v_actor->>'approved_name',v_status,v_revision.body,v_snapshot,v_note,
        case when v_status='approved' then 1 else null end,
        case when v_status='approved' then p_quality else null end)
      returning id into v_event;
    update public.concept_revisions set status=v_status where id=p_revision_id;
    if p_action='changes_requested' and coalesce(p_auto_correction,false) then
      if not coalesce(p_generation_enabled,false) then
        v_generation_status := 'disabled';
      elsif exists(select 1 from public.concept_revisions r
          where r.concept_id=v_revision.concept_id and
            r.created_at>v_revision.created_at)
        or exists(select 1 from public.editorial_generation_jobs j
          where j.source_revision_id=p_revision_id or
            (j.concept_id=v_revision.concept_id and
              j.status in ('pending','generating')))
        or (select count(*) from public.editorial_generation_jobs j
          where j.topic_id=v_concept.topic_id and
            j.status in ('pending','generating'))>=p_queue_limit
        or not coalesce(p_body_valid,false) then
        v_generation_status := 'unavailable';
      else
        insert into public.editorial_workflow_events
          (revision_id,concept_id,topic_id,actor_id,registered_name,
           action,note,details)
          values(p_revision_id,v_revision.concept_id,v_concept.topic_id,p_user_id,
            v_actor->>'approved_name','generation_requested',v_note,
            jsonb_build_object('kind','automatic_review',
              'feedback_event_id',v_event)) returning id into v_request_event;
        v_source_token := encode(pg_catalog.sha256(convert_to(
          public.edge_api_editorial_python_json(jsonb_build_object(
            'revision',public.edge_api_editorial_revision_token(p_revision_id),
            'siblings',(select coalesce(jsonb_agg(r.id order by r.id),'[]'::jsonb)
              from public.concept_revisions r
              where r.concept_id=v_revision.concept_id))),
          'UTF8')),'hex');
        insert into public.editorial_generation_jobs
          (source_revision_id,concept_id,topic_id,feedback_event_id,
           request_event_id,requested_by,source_token,source_body,feedback)
          values(p_revision_id,v_revision.concept_id,v_concept.topic_id,v_event,
            v_request_event,p_user_id,v_source_token,v_revision.body,v_note);
        v_generation_status := 'queued';
      end if;
    end if;
  elsif p_action='assign' then
    if v_revision.status in ('published','retired') then
      return jsonb_build_object('error','review_conflict',
        'message','Only open review work can be assigned');
    end if;
    if p_assignee_id is not null then
      select * into v_assignee from public.editorial_memberships
        where user_id=p_assignee_id;
      if not found or v_assignee.status<>'active' or
        v_assignee.approved_name is null or
        not (v_assignee.capabilities @> array['review']::text[]) then
        return jsonb_build_object('error','review_conflict',
          'message','Choose an active, approved reviewer');
      end if;
    end if;
    update public.concept_revisions set assigned_to=p_assignee_id,
      review_due_at=case when coalesce(p_has_due,false) then p_due_at
        else v_revision.review_due_at end where id=p_revision_id;
    insert into public.editorial_workflow_events
      (revision_id,concept_id,actor_id,registered_name,action,note,details)
      values(p_revision_id,v_revision.concept_id,p_user_id,
        v_actor->>'approved_name','assigned',v_note,jsonb_build_object(
          'previous_assignee',v_revision.assigned_to,
          'assignee',p_assignee_id,
          'previous_due_at',public.edge_api_editorial_utc_iso(v_revision.review_due_at),
          'review_due_at',public.edge_api_editorial_utc_iso(
            case when coalesce(p_has_due,false) then p_due_at
              else v_revision.review_due_at end)));
  elsif p_action='comment' then
    insert into public.editorial_workflow_events
      (revision_id,concept_id,actor_id,registered_name,action,note,details)
      values(p_revision_id,v_revision.concept_id,p_user_id,
        v_actor->>'approved_name','comment',v_note,'{}'::jsonb);
  end if;

  if p_action in ('publish','approve_and_publish') then
    select * into v_approval from public.editorial_revision_events
      where revision_id=p_revision_id and action='approved';
    if not found then
      return jsonb_build_object('error','review_conflict',
        'message','Authenticated approval of this exact revision is required');
    end if;
    if v_revision.status='published' then
      select content_version into v_version from public.editorial_publications
        where approval_id=v_approval.id;
      if v_version is null then
        return jsonb_build_object('error','review_conflict',
          'message','Published revision has no authenticated provenance');
      end if;
    else
      if p_action='publish' and v_revision.status<>'approved' then
        return jsonb_build_object('error','review_conflict',
          'message','Only an approved, non-retired revision can be published');
      end if;
      if v_approval.revision_body<>v_revision.body or
        v_approval.base_version<>v_revision.base_version or
        v_approval.source_snapshot<>v_snapshot then
        return jsonb_build_object('error','review_conflict',
          'message','Approved content or source version changed; prepare a new revision');
      end if;
      if not coalesce(p_body_valid,false) then
        return jsonb_build_object('error','review_conflict',
          'message','Revision body is invalid');
      end if;
      v_problem := public.edge_api_editorial_candidate_problem(
        v_concept.id,v_concept.slug,v_revision.body);
      if v_problem is not null then
        return jsonb_build_object('error','review_conflict','message',v_problem);
      end if;
      insert into public.concept_revisions
        (concept_id,base_version,body,status,review_note)
        select c.id,c.content_version-1,jsonb_build_object(
          'title',c.title,'summary',c.summary,'example',c.example,
          'flashcard',c.flashcard,'mcqs',c.mcqs,'curriculum',c.curriculum,
          'subtopic_slug',s.slug,'model',c.model,'prompt_version',c.prompt_version),
          'published',
          'Legacy version captured before correction; original review was not recorded.'
        from public.concepts c join public.subtopics s on s.id=c.subtopic_id
        where c.id=v_concept.id and c.content_version>0
          and not exists(select 1 from public.concept_revisions r
            where r.concept_id=c.id and r.status='published'
              and r.base_version=c.content_version-1);
      update public.concepts set
        title=v_revision.body->>'title',summary=v_revision.body->>'summary',
        example=v_revision.body->>'example',
        flashcard=v_revision.body->'learning_package'->'flashcard',
        mcqs=v_revision.body->'learning_package'->'mcqs',
        curriculum=v_revision.body->'curriculum',
        difficulty=(v_revision.body->'curriculum'->>'difficulty')::integer,
        model=v_revision.body->>'model',
        prompt_version=v_revision.body->>'prompt_version',
        content_version=content_version+1,status='published',published_at=now()
        where id=v_concept.id returning content_version into v_version;
      update public.concept_revisions set status='published',
        reviewed_by=v_approval.registered_name,
        review_note=v_approval.note,
        quality_review=v_approval.quality_review,
        reviewed_at=now() where id=p_revision_id;
      insert into public.editorial_publications
        (concept_id,content_version,approval_id,snapshot)
        select c.id,c.content_version,v_approval.id,
          to_jsonb(c)-array['created_at','published_at','status']
          from public.concepts c where c.id=v_concept.id;
      insert into public.editorial_revision_events
        (revision_id,concept_id,base_version,actor_id,registered_name,
         action,revision_body,source_snapshot,note)
        values(p_revision_id,v_revision.concept_id,v_revision.base_version,
          p_user_id,v_actor->>'approved_name','published',
          v_revision.body,v_snapshot,v_note);
    end if;
  end if;
  select r.status into v_status from public.concept_revisions r
    where r.id=p_revision_id;
  v_result := jsonb_build_object(
    'revision_id',p_revision_id,'status',v_status,
    'token',public.edge_api_editorial_revision_token(p_revision_id),
    'published_version',v_version,
    'generation_status',v_generation_status);
  insert into public.editorial_request_receipts
    (actor_id,request_id,fingerprint,result)
    values(p_user_id,p_request_id,p_fingerprint,v_result);
  return v_result;
end
$function$

edge_api_editorial_revision_generation.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_revision_generation(p_user_id uuid, p_session_id uuid, p_aal text, p_revision_id uuid, p_request_id uuid, p_note text, p_expected_token text, p_enabled boolean, p_queue_limit integer, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_receipt public.editorial_request_receipts%rowtype;
  v_revision public.concept_revisions%rowtype;
  v_concept public.concepts%rowtype;
  v_topic_active boolean;
  v_subtopic_active boolean;
  v_subtopic_slug text;
  v_snapshot jsonb;
  v_token text;
  v_source_token text;
  v_feedback public.editorial_revision_events%rowtype;
  v_event uuid;
  v_job public.editorial_generation_jobs%rowtype;
  v_result jsonb;
  v_note text;
begin
  if p_revision_id is null or p_request_id is null or p_note is null
    or length(p_note)<10 or length(p_note)>4000
    or p_expected_token is null or p_expected_token !~ '^[a-f0-9]{64}$'
    or p_queue_limit is null or p_queue_limit<1 or p_queue_limit>250
    or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('error','invalid');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'review');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'request_generation');
  if v_actor ? 'error' then return v_actor; end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'review');
  if v_actor ? 'error' then return v_actor; end if;
  select * into v_receipt from public.editorial_request_receipts
    where actor_id=p_user_id and request_id=p_request_id;
  if found then
    if v_receipt.fingerprint<>p_fingerprint then
      return jsonb_build_object('error','receipt_conflict');
    end if;
    return v_receipt.result;
  end if;
  if not coalesce(p_enabled,false) then
    return jsonb_build_object('error','generation_disabled');
  end if;
  select r.* into v_revision from public.concept_revisions r
    where r.id=p_revision_id for update;
  if not found then return jsonb_build_object('error','revision_not_found'); end if;
  select c.* into v_concept from public.concepts c
    join public.topics t on t.id=c.topic_id
    join public.subtopics s on s.id=c.subtopic_id
    where c.id=v_revision.concept_id for update of c,t,s;
  select t.is_active,s.is_active,s.slug into
    v_topic_active,v_subtopic_active,v_subtopic_slug
    from public.topics t join public.subtopics s on s.topic_id=t.id
    where s.id=v_concept.subtopic_id;
  v_snapshot := to_jsonb(v_concept)-array['created_at','published_at','status'];
  v_token := encode(pg_catalog.sha256(convert_to(
    public.edge_api_editorial_python_json(jsonb_build_object(
      'id',v_revision.id,'concept_id',v_revision.concept_id,
      'base_version',v_revision.base_version,'body',v_revision.body,
      'status',v_revision.status,'assigned_to',v_revision.assigned_to,
      'review_due_at',public.edge_api_editorial_utc_iso(v_revision.review_due_at),
      'source_snapshot',v_snapshot,'concept_status',v_concept.status,
      'topic_active',v_topic_active,'subtopic_active',v_subtopic_active,
      'subtopic_slug',v_subtopic_slug)), 'UTF8')),'hex');
  if v_token<>p_expected_token then
    return jsonb_build_object('error','stale_revision');
  end if;
  if v_revision.base_version<>v_concept.content_version
    or v_concept.status='archived' or not v_topic_active or not v_subtopic_active then
    return jsonb_build_object('error','review_conflict',
      'message','Revision is stale or content is retired');
  end if;
  if v_revision.status<>'changes_requested' then
    return jsonb_build_object('error','review_conflict',
      'message','Record a changes-requested decision on this revision first');
  end if;
  if exists(select 1 from public.concept_revisions r
    where r.concept_id=v_revision.concept_id and r.created_at>v_revision.created_at) then
    return jsonb_build_object('error','review_conflict',
      'message','A newer revision exists; review it before requesting AI changes');
  end if;
  if exists(select 1 from public.editorial_generation_jobs j
    where j.source_revision_id=p_revision_id or
      (j.concept_id=v_revision.concept_id and j.status in ('pending','generating'))) then
    return jsonb_build_object('error','review_conflict',
      'message','AI work already exists; inspect its status or stage a new revision');
  end if;
  if (select count(*) from public.editorial_generation_jobs j
    where j.topic_id=v_concept.topic_id and j.status in ('pending','generating'))
    >=p_queue_limit then
    return jsonb_build_object('error','review_conflict',
      'message','Revision generation queue is full; finish or cancel outstanding work first');
  end if;
  select * into v_feedback from public.editorial_revision_events e
    where e.revision_id=p_revision_id and e.action='changes_requested'
    order by e.created_at desc,e.id desc limit 1;
  if not found then
    return jsonb_build_object('error','review_conflict',
      'message','Changes-requested review evidence is missing');
  end if;
  v_note := regexp_replace(p_note,'^[[:space:]]+|[[:space:]]+$','','g');
  if length(v_note)<10 then
    return jsonb_build_object('error','review_conflict',
      'message','Record a substantive note of at least 10 characters');
  end if;
  insert into public.editorial_workflow_events
    (revision_id,concept_id,topic_id,actor_id,registered_name,action,note,details)
    values(p_revision_id,v_revision.concept_id,v_concept.topic_id,p_user_id,
      v_actor->>'approved_name','generation_requested',v_note,
      jsonb_build_object('kind','revision','feedback_event_id',v_feedback.id))
    returning id into v_event;
  v_source_token := encode(pg_catalog.sha256(convert_to(
    public.edge_api_editorial_python_json(jsonb_build_object(
      'revision',v_token,'siblings',(
        select coalesce(jsonb_agg(r.id order by r.id),'[]'::jsonb)
        from public.concept_revisions r where r.concept_id=v_revision.concept_id))),
      'UTF8')),'hex');
  insert into public.editorial_generation_jobs
    (source_revision_id,concept_id,topic_id,feedback_event_id,request_event_id,
     requested_by,source_token,source_body,feedback)
    values(p_revision_id,v_revision.concept_id,v_concept.topic_id,v_feedback.id,v_event,
      p_user_id,v_source_token,v_revision.body,v_feedback.note)
    returning * into v_job;
  v_token := encode(pg_catalog.sha256(convert_to(
    public.edge_api_editorial_python_json(jsonb_build_object(
      'id',v_job.id,'status',v_job.status,'attempts',v_job.attempts,
      'updated_at',public.edge_api_editorial_utc_iso(v_job.updated_at))),
      'UTF8')),'hex');
  v_result := jsonb_build_object(
    'id',v_job.id,'source_revision_id',v_job.source_revision_id,
    'concept_id',v_job.concept_id,'topic_id',v_job.topic_id,
    'feedback_event_id',v_job.feedback_event_id,
    'request_event_id',v_job.request_event_id,
    'status',v_job.status,'attempts',v_job.attempts,
    'available_at',public.edge_api_editorial_utc_iso(v_job.available_at),
    'result_revision_id',v_job.result_revision_id,
    'failure_code',v_job.failure_code,
    'created_at',public.edge_api_editorial_utc_iso(v_job.created_at),
    'updated_at',public.edge_api_editorial_utc_iso(v_job.updated_at),
    'token',v_token);
  insert into public.editorial_request_receipts
    (actor_id,request_id,fingerprint,result)
    values(p_user_id,p_request_id,p_fingerprint,v_result);
  return v_result;
end
$function$

edge_api_editorial_revision_history.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_revision_history(p_user_id uuid, p_session_id uuid, p_aal text, p_concept_id uuid, p_cursor uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_items jsonb;
  v_next uuid;
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    return jsonb_build_object('error', 'invalid_page');
  end if;
  v_actor := public.edge_api_editorial_authorize_any(
    p_user_id, p_session_id, p_aal, array['review','approve','publish']);
  if v_actor ? 'error' then return v_actor; end if;
  if p_concept_id is null or not exists(
    select 1 from public.concepts where id=p_concept_id
  ) then
    return jsonb_build_object('error', 'concept_not_found');
  end if;
  with page as (
    select r.id, jsonb_build_object(
      'id',r.id,'base_version',r.base_version,'status',r.status,
      'created_at',public.edge_api_editorial_utc_iso(r.created_at),'assigned_to',r.assigned_to
    ) as item
    from public.concept_revisions r
    where r.concept_id=p_concept_id and (p_cursor is null or r.id>p_cursor)
    order by r.id limit p_limit+1
  ), numbered as (
    select page.*,row_number() over(order by id) as position from page
  )
  select coalesce(jsonb_agg(item order by id) filter(where position<=p_limit), '[]'::jsonb),
         (select id from numbered where position=p_limit
           and exists(select 1 from numbered where position>p_limit))
    into v_items,v_next from numbered;
  return jsonb_build_object('items',v_items,'next_cursor',v_next);
end
$function$

edge_api_editorial_stage_revision.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_stage_revision(p_user_id uuid, p_session_id uuid, p_aal text, p_concept_id uuid, p_request_id uuid, p_note text, p_expected_token text, p_body jsonb, p_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_receipt public.editorial_request_receipts%rowtype;
  v_concept public.concepts%rowtype;
  v_topic_active boolean;
  v_subtopic_active boolean;
  v_subtopic_slug text;
  v_revision_id uuid;
  v_note text;
  v_problem text;
  v_snapshot jsonb;
  v_token text;
  v_result jsonb;
begin
  if p_concept_id is null or p_request_id is null or p_note is null
    or length(p_note)<10 or length(p_note)>4000
    or p_expected_token is null or p_expected_token !~ '^[a-f0-9]{64}$'
    or jsonb_typeof(p_body)<>'object'
    or p_fingerprint is null or p_fingerprint !~ '^[a-f0-9]{64}$' then
    return jsonb_build_object('error','invalid');
  end if;
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'review');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(274,263);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'review');
  if v_actor ? 'error' then return v_actor; end if;
  perform pg_catalog.pg_advisory_xact_lock(195,1);
  v_actor := public.edge_api_editorial_authorize(
    p_user_id,p_session_id,p_aal,'review');
  if v_actor ? 'error' then return v_actor; end if;
  select * into v_receipt from public.editorial_request_receipts
    where actor_id=p_user_id and request_id=p_request_id;
  if found then
    if v_receipt.fingerprint<>p_fingerprint then
      return jsonb_build_object('error','receipt_conflict');
    end if;
    return v_receipt.result;
  end if;
  select c.* into v_concept
    from public.concepts c
    join public.topics t on t.id=c.topic_id
    join public.subtopics s on s.id=c.subtopic_id
    where c.id=p_concept_id for update of c,t,s;
  if not found then return jsonb_build_object('error','concept_not_found'); end if;
  select t.is_active,s.is_active,s.slug into
    v_topic_active,v_subtopic_active,v_subtopic_slug
    from public.topics t join public.subtopics s on s.topic_id=t.id
    where s.id=v_concept.subtopic_id;
  v_snapshot := to_jsonb(v_concept)-array['created_at','published_at','status'];
  v_token := encode(pg_catalog.sha256(convert_to(
    public.edge_api_editorial_python_json(jsonb_build_object(
      'snapshot',v_snapshot,'status',v_concept.status,
      'topic_active',v_topic_active,'subtopic_active',v_subtopic_active,
      'subtopic_slug',v_subtopic_slug)), 'UTF8')),'hex');
  if v_token<>p_expected_token then
    return jsonb_build_object('error','stale_revision');
  end if;
  if v_concept.status='archived' or not v_topic_active or not v_subtopic_active then
    return jsonb_build_object('error','review_conflict',
      'message','Cannot stage retired content');
  end if;
  if p_body->>'subtopic_slug' is distinct from v_subtopic_slug then
    return jsonb_build_object('error','review_conflict',
      'message','A revision cannot change a concept''s approved subtopic');
  end if;
  -- The Edge parser validates the complete body shape. Repeat the graph check
  -- under the catalog lock, so a concurrent catalog edit cannot change it.
  with recursive walk(slug,route,cycle) as (
    select prereq.value, array[v_concept.slug,prereq.value],
      prereq.value=v_concept.slug
      from jsonb_array_elements_text(coalesce(
        p_body->'curriculum'->'prerequisites','[]'::jsonb)) prereq(value)
    union all
    select child.value, walk.route||child.value,
      child.value=any(walk.route)
      from walk
      left join public.concepts known_concept on known_concept.slug=walk.slug
      left join public.concept_backlog known_backlog on known_backlog.slug=walk.slug
      cross join lateral jsonb_array_elements_text(coalesce(
        known_concept.curriculum->'prerequisites',
        known_backlog.curriculum->'prerequisites','[]'::jsonb)) child(value)
      where not walk.cycle and cardinality(walk.route)<1000
  )
  select case when cycle then 'Prerequisite cycle includes '||slug
    when not exists(select 1 from public.concepts c where c.slug=walk.slug)
      and not exists(select 1 from public.concept_backlog b where b.slug=walk.slug)
      then 'Unknown prerequisite '||slug end
    into v_problem from walk
    where cycle or (not exists(select 1 from public.concepts c where c.slug=walk.slug)
      and not exists(select 1 from public.concept_backlog b where b.slug=walk.slug))
    limit 1;
  if v_problem is not null then
    return jsonb_build_object('error','review_conflict','message',v_problem);
  end if;
  v_note := regexp_replace(p_note,'^[[:space:]]+|[[:space:]]+$','','g');
  if length(v_note)<10 then
    return jsonb_build_object('error','review_conflict',
      'message','Record a substantive note of at least 10 characters');
  end if;
  insert into public.concept_revisions(concept_id,base_version,body)
    values(p_concept_id,v_concept.content_version,p_body) returning id into v_revision_id;
  insert into public.editorial_workflow_events
    (revision_id,concept_id,topic_id,actor_id,registered_name,action,note,details)
    values(v_revision_id,p_concept_id,null,p_user_id,
      v_actor->>'approved_name','staged',v_note,
      jsonb_build_object('base_version',v_concept.content_version));
  v_token := encode(pg_catalog.sha256(convert_to(
    public.edge_api_editorial_python_json(jsonb_build_object(
      'id',v_revision_id,'concept_id',p_concept_id,
      'base_version',v_concept.content_version,'body',p_body,
      'status','draft','assigned_to',null,'review_due_at',null,
      'source_snapshot',v_snapshot,
      'concept_status',v_concept.status,'topic_active',v_topic_active,
      'subtopic_active',v_subtopic_active,'subtopic_slug',v_subtopic_slug)),
      'UTF8')),'hex');
  v_result := jsonb_build_object(
    'revision_id',v_revision_id,'status','draft','token',v_token);
  insert into public.editorial_request_receipts
    (actor_id,request_id,fingerprint,result)
    values(p_user_id,p_request_id,p_fingerprint,v_result);
  return v_result;
end
$function$

edge_api_editorial_taxonomy.definition:
CREATE OR REPLACE FUNCTION public.edge_api_editorial_taxonomy(p_user_id uuid, p_session_id uuid, p_aal text, p_cursor uuid, p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor jsonb;
  v_items jsonb;
  v_next uuid;
begin
  if p_limit is null or p_limit < 1 or p_limit > 100 then
    return jsonb_build_object('error', 'invalid_page');
  end if;
  v_actor := public.edge_api_editorial_authorize_any(
    p_user_id, p_session_id, p_aal, array['review','approve','publish']);
  if v_actor ? 'error' then return v_actor; end if;
  with page as (
    select s.id, jsonb_build_object(
      'id', s.id, 'name', s.name, 'is_active', s.is_active,
      'topic_id', t.id, 'topic_name', t.name, 'topic_active', t.is_active
    ) as item
      from public.subtopics s join public.topics t on t.id = s.topic_id
     where p_cursor is null or s.id > p_cursor
     order by s.id limit p_limit + 1
  ), numbered as (
    select page.*, row_number() over(order by id) as position from page
  )
  select coalesce(jsonb_agg(item order by id) filter(where position <= p_limit), '[]'::jsonb),
         (select id from numbered where position = p_limit
           and exists(select 1 from numbered where position > p_limit))
    into v_items, v_next from numbered;
  return jsonb_build_object('items', v_items, 'next_cursor', v_next);
end
$function$

edge_api_push_token.definition:
CREATE OR REPLACE FUNCTION public.edge_api_push_token(p_user_id uuid, p_token text, p_platform text, p_register boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_register is null then
    raise exception 'Invalid push-token action';
  end if;
  if p_register then
    if p_token is null or length(p_token) not between 10 and 200
       or (p_platform is not null and p_platform not in ('ios', 'android')) then
      raise exception 'Invalid push token';
    end if;
    insert into public.device_tokens(user_id, expo_push_token, platform)
    values(p_user_id, p_token, p_platform)
    on conflict (expo_push_token) do update
      set user_id = excluded.user_id,
          platform = coalesce(excluded.platform, device_tokens.platform),
          last_seen_at = now();
  elsif p_token is null then
    delete from public.device_tokens where user_id = p_user_id;
  else
    delete from public.device_tokens
    where user_id = p_user_id and expo_push_token = p_token;
  end if;
  return true;
end
$function$

edge_api_set_avatar.definition:
CREATE OR REPLACE FUNCTION public.edge_api_set_avatar(p_user_id uuid, p_avatar_key text, p_compact boolean, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_old text;
  v_prefix text;
begin
  if p_user_id is null or p_compact is null then
    return jsonb_build_object('error','invalid');
  end if;
  v_prefix := 'avatars/'||p_user_id::text||'/';
  if p_avatar_key is not null and
    (left(p_avatar_key,length(v_prefix))<>v_prefix or
      substring(p_avatar_key from length(v_prefix)+1) !~ '^[a-f0-9]{32}[.]jpg$') then
    return jsonb_build_object('error','invalid');
  end if;
  select avatar_url into v_old from public.profiles
    where id=p_user_id for update;
  if not found then return null; end if;
  update public.profiles set avatar_url=p_avatar_key where id=p_user_id;
  return jsonb_build_object(
    'state',public.edge_api_profile_snapshot(p_user_id,p_compact,p_today),
    'old_avatar_ref',v_old);
end
$function$

edge_api_set_interaction.definition:
CREATE OR REPLACE FUNCTION public.edge_api_set_interaction(p_user_id uuid, p_slug text, p_kind text, p_on boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_concept_id uuid;
begin
  if p_kind not in ('like', 'save') or p_on is null then
    raise exception 'Invalid interaction';
  end if;

  select id into v_concept_id from public.concepts
  where slug = p_slug and status = 'published';
  if v_concept_id is null then
    return false;
  end if;

  if p_kind = 'like' then
    insert into public.concept_interactions(user_id, concept_id, liked_at)
    values (p_user_id, v_concept_id, case when p_on then now() else null end)
    on conflict (user_id, concept_id) do update
      set liked_at = excluded.liked_at, updated_at = now();
  else
    insert into public.concept_interactions(user_id, concept_id, saved_at)
    values (p_user_id, v_concept_id, case when p_on then now() else null end)
    on conflict (user_id, concept_id) do update
      set saved_at = excluded.saved_at, updated_at = now();
  end if;
  return true;
end
$function$

edge_api_state.definition:
CREATE OR REPLACE FUNCTION public.edge_api_state(p_user_id uuid, p_compact boolean, p_reviews boolean, p_low integer, p_reserve integer, p_active_days integer, p_today date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_profile record;
  v_daily jsonb;
  v_review jsonb;
  v_history jsonb;
  v_saved jsonb;
  v_stats jsonb;
  v_followed jsonb;
  v_likes jsonb;
  v_bookmarks jsonb;
  v_versions jsonb;
  v_older jsonb;
  v_availability text;
  v_assignment_slug text;
  v_limit integer;
begin
  if p_compact is null or p_reviews is null then
    raise exception 'Invalid state options';
  end if;
  -- Daily selection bootstraps a legacy profile, locks it, and owns today's slot.
  v_daily := public.edge_api_daily(
    p_user_id, p_low, p_reserve, p_active_days, p_today
  );
  select display_name, bio, avatar_url, timezone,
         coalesce(p_today, (now() at time zone timezone)::date) as today
    into v_profile from public.profiles where id = p_user_id;
  if not found then return null; end if;

  if v_daily->>'reason' is null then
    v_availability := 'available';
    v_assignment_slug := v_daily->'concept'->>'slug';
  elsif v_daily->>'reason' = 'personalization_required' then
    v_availability := 'personalization_required';
  else
    v_availability := 'catalog_exhausted';
    if p_reviews then
      v_review := public.edge_api_choose_review(p_user_id, v_profile.today);
      if v_review is not null then v_availability := 'review_available'; end if;
    end if;
  end if;
  if v_daily->>'reason' is not null then v_daily := null; end if;

  v_limit := case when p_compact then 50 else 2147483646 end;
  v_history := public.edge_api_history(p_user_id, null, v_limit);
  v_saved := public.edge_api_saved(p_user_id, null, null, v_limit);
  v_stats := public.edge_api_stats(p_user_id);

  select coalesce(jsonb_agg(t.slug order by t.sort_order), '[]'::jsonb)
    into v_followed from public.user_topics ut
    join public.topics t on t.id = ut.topic_id and t.is_active
   where ut.user_id = p_user_id;
  select coalesce(jsonb_agg(c.slug order by c.slug) filter (where i.liked_at is not null), '[]'::jsonb),
         coalesce(jsonb_agg(c.slug order by c.slug) filter (where i.saved_at is not null), '[]'::jsonb),
         coalesce(jsonb_agg(c.content_version order by c.slug) filter (where i.saved_at is not null), '[]'::jsonb)
    into v_likes, v_bookmarks, v_versions
    from public.concept_interactions i
    join public.concepts c on c.id = i.concept_id and c.status = 'published'
   where i.user_id = p_user_id;

  v_older := null;
  if p_compact then
    v_older := '{}'::jsonb;
    if v_history->>'next_cursor' is not null then
      select coalesce(jsonb_object_agg(topic_name, n), '{}'::jsonb)
        into v_older from (
          select t.name as topic_name, count(*)::integer as n
            from public.daily_assignments a
            join public.concepts c on c.id = a.concept_id and c.status = 'published'
            join public.topics t on t.id = c.topic_id
           where a.user_id = p_user_id and a.completed_at is not null
             and a.assigned_for < (v_history->>'next_cursor')::date
           group by t.name
        ) older;
    end if;
  end if;

  return jsonb_build_object(
    'display_name', v_profile.display_name, 'bio', v_profile.bio,
    'avatar_ref', v_profile.avatar_url, 'avatar_url', null,
    'timezone', v_profile.timezone, 'today', v_profile.today,
    'followed_topics', v_followed, 'learned', v_history->'items',
    'likes', v_likes, 'bookmarks', v_bookmarks,
    'bookmark_versions', v_versions, 'saved', v_saved->'items',
    'stats', v_stats, 'learned_before_window', v_older,
    'history_next_cursor', v_history->'next_cursor',
    'saved_next_cursor', v_saved->'next_cursor',
    'assignment_slug', v_assignment_slug,
    'daily', v_daily, 'daily_availability', v_availability,
    'review', v_review
  );
end
$function$

edge_api_subtopic_quiz.definition:
CREATE OR REPLACE FUNCTION public.edge_api_subtopic_quiz(p_user_id uuid, p_completion_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_completion record;
  v_quiz_id uuid;
  v_questions jsonb;
  v_public jsonb;
  v_reviewed integer;
  v_required integer;
begin
  if not exists(select 1 from auth.users where id = p_user_id) then return null; end if;
  with created as (
    insert into public.profiles(id, display_name)
    select p_user_id, split_part(u.email, '@', 1) from auth.users u
     where u.id = p_user_id
    on conflict(id) do nothing returning id
  )
  insert into public.user_topics(user_id, topic_id)
  select created.id, t.id from created cross join public.topics t where t.is_active
  on conflict do nothing;
  insert into public.notification_preferences(user_id) values(p_user_id)
  on conflict(user_id) do nothing;
  perform 1 from public.profiles where id = p_user_id for update;
  if not found then return null; end if;
  select e.catalog_concept_ids, t.name as topic_name, s.name as subtopic_name
    into v_completion from public.user_subtopic_completions e
    join public.subtopics s on s.id = e.subtopic_id
    join public.topics t on t.id = s.topic_id
   where e.id = p_completion_id and e.user_id = p_user_id;
  if not found then return jsonb_build_object('error', 'unavailable'); end if;
  select id, questions into v_quiz_id, v_questions from public.subtopic_quizzes
   where user_id = p_user_id and subtopic_completion_id = p_completion_id;
  if v_quiz_id is null then
    v_required := least(7, cardinality(v_completion.catalog_concept_ids));
    with candidates as (
      select c.id, c.slug, c.title, c.content_version, c.mcqs,
        pg_catalog.sha256(convert_to(p_completion_id::text || ':select:' || c.id::text, 'UTF8')) as sort_key,
        (get_byte(pg_catalog.sha256(convert_to(
          p_completion_id::text || ':' || c.id::text, 'UTF8')), 0) * 256
         + get_byte(pg_catalog.sha256(convert_to(
          p_completion_id::text || ':' || c.id::text, 'UTF8')), 1)) % 3 as question_index
        from public.concepts c
       where c.id = any(v_completion.catalog_concept_ids)
         and c.status = 'published' and jsonb_typeof(c.mcqs) = 'array'
         and jsonb_array_length(c.mcqs) = 3
       order by sort_key, c.id
       limit v_required
    )
    select count(*)::integer,
      coalesce(jsonb_agg(jsonb_build_object(
        'id', id::text || ':' || content_version::text || ':' || question_index::text,
        'concept_slug', slug, 'concept_title', title,
        'content_version', content_version,
        'question', mcqs -> question_index -> 'question',
        'options', mcqs -> question_index -> 'options',
        'correct_index', mcqs -> question_index -> 'correct_index'
      ) order by sort_key, id), '[]'::jsonb)
      into v_reviewed, v_questions from candidates;
    if v_reviewed < v_required then
      return jsonb_build_object('available', false, 'completion_id', p_completion_id,
        'topic_name', v_completion.topic_name, 'subtopic_name', v_completion.subtopic_name,
        'reviewed_concepts', v_reviewed, 'required_concepts', v_required,
        'detail', 'This optional quiz will unlock when enough reviewed questions are available.');
    end if;
    insert into public.subtopic_quizzes(user_id, subtopic_completion_id, questions)
    values(p_user_id, p_completion_id, v_questions) returning id into v_quiz_id;
  end if;
  select coalesce(jsonb_agg(q.value - 'correct_index' order by q.ordinality), '[]'::jsonb)
    into v_public from jsonb_array_elements(v_questions) with ordinality as q(value, ordinality);
  return jsonb_build_object('available', true, 'quiz_id', v_quiz_id,
    'completion_id', p_completion_id, 'topic_name', v_completion.topic_name,
    'subtopic_name', v_completion.subtopic_name, 'questions', v_public);
end
$function$

edge_api_weekly_quiz.definition:
CREATE OR REPLACE FUNCTION public.edge_api_weekly_quiz(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_week date := current_date - (extract(isodow from current_date)::integer - 1);
  v_quiz_id uuid;
  v_questions jsonb;
  v_public jsonb;
  v_count integer;
begin
  if not exists(select 1 from auth.users where id = p_user_id) then return null; end if;
  with created as (
    insert into public.profiles(id, display_name)
    select p_user_id, split_part(u.email, '@', 1) from auth.users u
     where u.id = p_user_id
    on conflict(id) do nothing returning id
  )
  insert into public.user_topics(user_id, topic_id)
  select created.id, t.id from created cross join public.topics t where t.is_active
  on conflict do nothing;
  insert into public.notification_preferences(user_id) values(p_user_id)
  on conflict(user_id) do nothing;
  perform 1 from public.profiles where id = p_user_id for update;
  if not found then return null; end if;

  select id, questions into v_quiz_id, v_questions
    from public.weekly_quizzes where user_id = p_user_id and week_start = v_week;
  if v_quiz_id is null then
    with recent as (
      select c.id, c.slug, c.title, c.content_version, c.mcqs,
             max(a.completed_at) as completed_at
        from public.daily_assignments a
        join public.concepts c on c.id = a.concept_id
       where a.user_id = p_user_id and a.completed_at is not null
         and c.status = 'published' and jsonb_typeof(c.mcqs) = 'array'
       group by c.id, c.slug, c.title, c.content_version, c.mcqs
      having jsonb_array_length(c.mcqs) = 3
       order by max(a.completed_at) desc, c.id
       limit 7
    ), selected as (
      select recent.*,
        (get_byte(pg_catalog.sha256(convert_to(
          p_user_id::text || ':' || v_week::text || ':' || recent.id::text, 'UTF8')), 0) * 256
         + get_byte(pg_catalog.sha256(convert_to(
          p_user_id::text || ':' || v_week::text || ':' || recent.id::text, 'UTF8')), 1)) % 3
        as question_index
      from recent
    )
    select count(*)::integer,
      coalesce(jsonb_agg(jsonb_build_object(
        'id', id::text || ':' || content_version::text || ':' || question_index::text,
        'concept_slug', slug, 'concept_title', title,
        'content_version', content_version,
        'question', mcqs -> question_index -> 'question',
        'options', mcqs -> question_index -> 'options',
        'correct_index', mcqs -> question_index -> 'correct_index'
      ) order by completed_at desc, id), '[]'::jsonb)
      into v_count, v_questions from selected;
    if v_count < 7 then
      return jsonb_build_object('available', false, 'week_start', v_week,
        'required_concepts', 7, 'available_concepts', v_count,
        'detail', 'Complete more concepts with reviewed questions to unlock this weekly quiz.');
    end if;
    insert into public.weekly_quizzes(user_id, week_start, questions)
    values(p_user_id, v_week, v_questions) returning id into v_quiz_id;
  end if;
  select coalesce(jsonb_agg(q.value - 'correct_index' order by q.ordinality), '[]'::jsonb)
    into v_public from jsonb_array_elements(v_questions) with ordinality as q(value, ordinality);
  return jsonb_build_object('available', true, 'quiz_id', v_quiz_id,
    'week_start', v_week, 'questions', v_public);
end
$function$

protect_editorial_job_input.definition:
CREATE OR REPLACE FUNCTION public.protect_editorial_job_input()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ begin
  if TG_OP='DELETE' then raise exception 'Editorial generation evidence cannot be deleted'; end if;
  if (to_jsonb(new)-array['status','attempts','claim_token','claimed_at','available_at','result_revision_id','failure_code','updated_at'])
     is distinct from
     (to_jsonb(old)-array['status','attempts','claim_token','claimed_at','available_at','result_revision_id','failure_code','updated_at'])
     or (old.result_revision_id is not null and new.result_revision_id is distinct from old.result_revision_id) then
    raise exception 'Editorial generation inputs and results are immutable';
  end if;
  return new;
end $function$

protect_generated_revision_body.definition:
CREATE OR REPLACE FUNCTION public.protect_generated_revision_body()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$ begin
  if (new.body,new.base_version,new.concept_id) is distinct from (old.body,old.base_version,old.concept_id)
    and exists(select 1 from public.editorial_generation_jobs
      where source_revision_id=old.id or result_revision_id=old.id) then
    raise exception 'Generated revision evidence is immutable; stage a new revision';
  end if;
  return new;
end $function$

touch_updated_at.definition:
CREATE OR REPLACE FUNCTION public.touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
